window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"volume-disk":{"id":"volume-disk","prerequisites":["area-under-curve","riemann-sum-intuition"],"next":["volume-washer"],"related":["area-dy"],"objectives":["把體積看成薄片疊起來：$V=\\int A(x)\\,dx$，$A(x)$ 是截面面積","旋轉體的截面是圓：繞 $x$ 軸時 $V=\\int\\pi f(x)^2\\,dx$","繞 $y$ 軸時把半徑寫成 $y$ 的函數，對 $y$ 積分","截面不是圓的立體也會用同一個想法"],"concept":[{"heading":"① 體積：截面疊起來","body":["想像把一條吐司切成很薄的片","在 $x$ 處切一刀，截面面積叫 $A(x)$；一片厚 $\\Delta x$：","片很薄時，一片幾乎是「底面積 × 高」的柱體","全部加起來：","片越切越薄，$\\Delta x\\to0$：","檢查：柱體的截面處處一樣，$A(x)=A$"],"tex":["\\Delta V\\approx A(x)\\,\\Delta x","V\\approx\\sum_{i=1}^{n}A(x_i)\\,\\Delta x","V=\\int_a^b A(x)\\,dx","V=\\int_a^b A\\,dx=A\\,(b-a)"]},{"heading":"① 先猜猜看","body":["這叫祖暅原理（也叫 Cavalieri 原理）","截面面積處處相等 → 體積相等"]},{"heading":"② 繞 x 軸：截面是圓盤","body":["區域：$0\\le y\\le f(x)$，$a\\le x\\le b$，繞 $x$ 軸轉一圈","在 $x$ 處垂直 $x$ 軸切：截面是一個圓盤","半徑 = 曲線到軸的距離 $=f(x)$","每一片是半徑 $f(x)$、厚 $dx$ 的薄圓柱：$\\pi f(x)^2\\,dx$"],"tex":["A(x)=\\pi\\,[f(x)]^2","V=\\int_a^b \\pi\\,[f(x)]^2\\,dx"]},{"heading":"② 例：$y=\\sqrt x$ 繞 $x$ 軸","body":["$y=\\sqrt x$，$0\\le x\\le4$，與 $x$ 軸之間的區域繞 $x$ 軸","半徑 $f(x)=\\sqrt x$，截面 $A(x)=\\pi(\\sqrt x)^2=\\pi x$","對照：外面套一個半徑 $2$、長 $4$ 的圓柱：$\\pi\\cdot2^2\\cdot4=16\\pi$","拋物線轉出來的「碗」叫旋轉拋物面；體積是外接圓柱的一半"],"tex":["V=\\int_0^4\\pi x\\,dx=\\pi\\Big[\\frac{x^2}{2}\\Big]_0^4=8\\pi"]},{"heading":"② 例：球的體積公式","body":["半圓 $y=\\sqrt{r^2-x^2}$，$-r\\le x\\le r$，繞 $x$ 軸 → 半徑 $r$ 的球","截面半徑 $\\sqrt{r^2-x^2}$：$A(x)=\\pi(r^2-x^2)$"],"tex":["V=\\pi\\Big[r^2x-\\frac{x^3}{3}\\Big]_{-r}^{r}=\\pi\\Big(2r^3-\\frac{2r^3}{3}\\Big)","V=\\frac43\\pi r^3"]},{"heading":"③ 繞 y 軸：半徑換成 y","body":["區域：$y=x^2$（$0\\le x\\le1$）、$y$ 軸、$y=1$ 所圍，繞 $y$ 軸","垂直 $y$ 軸切：水平的薄片，厚度是 $dy$","半徑 = 到 $y$ 軸的距離 = $x$，寫成 $y$：$x=\\sqrt y$","繞 $y$ 軸，$x=g(y)$："],"tex":["A(y)=\\pi(\\sqrt y)^2=\\pi y","V=\\int_0^1\\pi y\\,dy=\\frac{\\pi}{2}","V=\\int_c^d\\pi\\,[g(y)]^2\\,dy"]},{"heading":"③ 試一題","body":["口訣：片垂直於軸；對片的厚度方向積分","如果改成 $y=x^2$ 下方（$x$ 軸、$x=1$）繞 $y$ 軸？","水平切片中間會空一段：截面是有洞的圓","下一課：$A=\\pi(R^2-r^2)$"]},{"heading":"④ 截面不是圓也可以","body":["底面是圓盤 $x^2+y^2\\le4$；垂直 $x$ 軸的截面都是正方形，一邊落在底面","在 $x$ 處，底面的弦從 $y=-\\sqrt{4-x^2}$ 到 $\\sqrt{4-x^2}$：","想法跟圓盤法完全一樣：先找截面面積 $A(x)$，再積分"],"tex":["s=2\\sqrt{4-x^2}","A(x)=s^2=4(4-x^2)","V=\\int_{-2}^{2}4(4-x^2)\\,dx=4\\Big[4x-\\frac{x^3}{3}\\Big]_{-2}^{2}=\\frac{128}{3}"]},{"heading":"④ 試一題","body":["步驟都一樣：","1. 決定切的方向（垂直哪一軸）","2. 寫出截面面積 $A(x)$","3. 找出 $x$ 的範圍，積分"]},{"heading":"重點整理","body":["• 體積 = 截面面積的積分：$V=\\int_a^b A(x)\\,dx$","• 繞 $x$ 軸：$V=\\int_a^b\\pi f(x)^2\\,dx$（圓盤）","• 繞 $y$ 軸：半徑寫成 $y$ 的函數，$V=\\int_c^d\\pi g(y)^2\\,dy$","• 片垂直於軸，對厚度的方向積分","• 截面是正方形、三角形……：一樣先找 $A(x)$","下一課：墊圈法（中間有洞）"]}],"workedExamples":[{"title":"繞 $x$ 軸","prompt":"$y=\\sqrt{x}$，$0\\le x\\le 4$ 與 $x$ 軸之間的區域繞 $x$ 軸旋轉，求體積。","problemId":"cx-rev-001","steps":["在 $x$ 處的截面是圓，半徑 $\\sqrt{x}$，面積 $A(x)=\\pi(\\sqrt{x})^2=\\pi x$。","$V=\\int_0^4\\pi x\\,dx=\\pi\\left[\\frac{x^2}{2}\\right]_0^4=8\\pi$。"],"answer":"$8\\pi$"},{"title":"繞 $y$ 軸","prompt":"$y=x^2$（$0\\le x\\le 1$）、$y$ 軸與 $y=1$ 所圍區域繞 $y$ 軸旋轉，求體積。","problemId":"cx-rev-004","steps":["繞 $y$ 軸，所以水平切、對 $y$ 積分。$y$ 的範圍是 0 到 1。","在高度 $y$，截面圓的半徑是曲線到 $y$ 軸的距離 $x$。由 $y=x^2$、$x\\ge 0$ 得 $x=\\sqrt{y}$。","$A(y)=\\pi(\\sqrt{y})^2=\\pi y$，$V=\\int_0^1\\pi y\\,dy=\\frac{\\pi}{2}$。"],"answer":"$\\frac{\\pi}{2}$"},{"title":"截面是正方形","prompt":"立體的底面是圓盤 $x^2+y^2\\le 4$；垂直於 $x$ 軸的每個截面都是正方形，一邊落在底面上。求體積。","problemId":"lec-09-q4b","steps":["在 $x$ 處，底面那條弦從 $y=-\\sqrt{4-x^2}$ 到 $y=\\sqrt{4-x^2}$，長 $2\\sqrt{4-x^2}$，這就是正方形的邊長。","$A(x)=(2\\sqrt{4-x^2})^2=4(4-x^2)$。","$V=\\int_{-2}^2 4(4-x^2)\\,dx=4\\left[4x-\\frac{x^3}{3}\\right]_{-2}^2=4\\cdot\\frac{32}{3}=\\frac{128}{3}$。"],"answer":"$\\frac{128}{3}$"}],"pitfalls":["半徑忘了平方，寫成 $\\int\\pi f(x)\\,dx$。","把圓周長 $2\\pi r$ 當成截面面積。","繞 $y$ 軸卻對 $x$ 積分、半徑還用 $f(x)$。","截面是正方形或三角形時也乘了 $\\pi$。","正方形的邊長只取半條弦。"],"voice":"06a4e85c","sections":[{"title":"體積：截面疊起來","beats":[{"show":["想像把一條吐司切成很薄的片"],"say":"先想像一條吐司。把它切成很多很薄的片，整條的體積，就是每一片的體積加起來。","board":[{"do":"write","line":"想像把一條吐司切成很薄的片"}],"t":[2980,14270]},{"show":["在 $x$ 處切一刀，截面面積叫 $A(x)$；一片厚 $\\Delta x$：","$\\Delta V\\approx A(x)\\,\\Delta x$"],"say":"沿著 x 軸切。在 x 這個位置切一刀，切口的面積叫 A x。一片的厚度是德爾塔 x，這一片的體積大約是面積乘厚度。","board":[{"do":"write","line":"在 $x$ 處切一刀，截面面積叫 $A(x)$；一片厚 $\\Delta x$："},{"do":"write","line":"$\\displaystyle \\Delta V\\approx A(x)\\,\\Delta x$","on":"切口"},{"do":"write","line":"　片很薄時，一片幾乎是「底面積 × 高」的柱體","color":"violet","on":"爾塔"}],"t":[14270,28050]},{"show":["全部加起來：","$V\\approx\\sum_{i=1}^{n}A(x_i)\\,\\Delta x$"],"say":"把 a 到 b 之間每一片加起來，就是一個黎曼和。","board":[{"do":"write","line":"全部加起來："},{"do":"write","line":"$\\displaystyle V\\approx\\sum_{i=1}^{n}A(x_i)\\,\\Delta x$","on":"片加"}],"t":[28050,35510]},{"show":["片越切越薄，$\\Delta x\\to0$：","$V=\\int_a^b A(x)\\,dx$"],"say":"片越切越薄，黎曼和就變成定積分。體積，就是截面面積從 a 積到 b。","board":[{"do":"write","line":"片越切越薄，$\\Delta x\\to0$："},{"do":"write","line":"${{bx1:\\displaystyle V=\\int_a^b A(x)\\,dx}}$","color":"red","on":"成定"},{"do":"box","term":"bx1","color":"red","on":"面面"}],"t":[35510,45670]},{"show":["檢查：柱體的截面處處一樣，$A(x)=A$","$V=\\int_a^b A\\,dx=A\\,(b-a)$"],"say":"檢查一下：柱體每個地方的截面都一樣，積分出來是面積乘長度，就是熟悉的底面積乘高。","board":[{"do":"write","line":"檢查：柱體的截面處處一樣，$A(x)=A$"},{"do":"write","line":"$\\displaystyle V=\\int_a^b A\\,dx=A\\,(b-a)$","on":"出來"}],"t":[45670,55420]}]},{"title":"先猜猜看","beats":[{"show":["兩個立體放在同一張桌上，每個高度的截面面積都一樣，形狀卻不同。它們的體積？"],"say":"先猜猜看。","t":[55420,66460]}],"predict":{"ask":"兩個立體放在同一張桌上，==每個高度==的截面面積都一樣，形狀卻不同。它們的體積？","options":[{"label":"一定相等","correct":true},{"label":"不一定，要看形狀","why":"公式裡只有 $A(x)$；面積處處相等，積分就相等"},{"label":"截面比較圓的那個比較大","why":"形狀不影響面積，也就不影響體積"}]}},{"title":"先猜猜看","beats":[{"show":["這叫祖暅原理（也叫 Cavalieri 原理）"],"say":"答案是一定相等。這個事實叫做祖暅原理，西方叫卡瓦列里原理。","board":[{"do":"write","line":"這叫祖暅原理（也叫 Cavalieri 原理）"}],"t":[66460,74070]},{"show":["截面面積處處相等 → 體積相等"],"say":"它就是體積公式的直接結果：體積只由截面面積決定。所以接下來的關鍵，都是寫出截面面積。","board":[{"do":"write","line":"截面面積處處相等 → 體積相等","color":"gold"}],"t":[74070,85030]}]},{"title":"繞 x 軸：截面是圓盤","beats":[{"show":["區域：$0\\le y\\le f(x)$，$a\\le x\\le b$，繞 $x$ 軸轉一圈"],"say":"現在看最常見的立體：旋轉體。把曲線 y 等於 f of x 和 x 軸之間的區域，繞 x 軸轉一圈。","board":[{"do":"write","line":"區域：$0\\le y\\le f(x)$，$a\\le x\\le b$，繞 $x$ 軸轉一圈"}],"t":[85030,95430]},{"show":["在 $x$ 處垂直 $x$ 軸切：截面是一個圓盤"],"say":"在 x 這個位置，垂直 x 軸切一刀。區域裡那一條直的線段，轉一圈就是一個圓盤。","board":[{"do":"write","line":"在 $x$ 處垂直 $x$ 軸切：截面是一個圓盤"}],"t":[95430,106050]},{"show":["半徑 = 曲線到軸的距離 $=f(x)$","$A(x)=\\pi\\,[f(x)]^2$"],"say":"圓盤的半徑，是曲線到 x 軸的距離，也就是 f of x。面積就是派乘 f of x 的平方。","board":[{"do":"write","line":"半徑 = 曲線到軸的距離 $=f(x)$"},{"do":"write","line":"$\\displaystyle A(x)=\\pi\\,[f(x)]^2$","on":"of#1"}],"t":[106050,115850]},{"show":["$V=\\int_a^b \\pi\\,[f(x)]^2\\,dx$"],"say":"代進體積公式，得到圓盤法：派乘 f of x 平方，從 a 積到 b。","board":[{"do":"write","line":"${{bx2:\\displaystyle V=\\int_a^b \\pi\\,[f(x)]^2\\,dx}}$","color":"red"},{"do":"box","term":"bx2","color":"red","on":"of"}],"t":[115850,123950]},{"show":["圖"],"say":"圖上，黃色那一片就是一個圓盤，紅色的線是它的半徑 f of x。整個立體，就是無數個這樣的薄圓盤疊起來。","board":[{"do":"plot","svg":"<svg viewBox=\"0 0 620 270\" width=\"620\"><line x1=\"30\" y1=\"130\" x2=\"600\" y2=\"130\" stroke=\"var(--muted)\" stroke-width=\"2\" stroke-dasharray=\"8 6\"/><polyline points=\"80.0,130.0 91.0,112.6 102.0,105.4 113.0,99.9 124.0,95.2 135.0,91.1 146.0,87.4 157.0,84.0 168.0,80.8 179.0,77.8 190.0,75.0 201.0,72.3 212.0,69.8 223.0,67.3 234.0,64.9 245.0,62.6 256.0,60.4 267.0,58.3 278.0,56.2 289.0,54.2 300.0,52.2 311.0,50.3 322.0,48.4 333.0,46.6 344.0,44.8 355.0,43.0 366.0,41.3 377.0,39.6 388.0,38.0 399.0,36.3 410.0,34.7 421.0,33.2 432.0,31.6 443.0,30.1 454.0,28.6 465.0,27.1 476.0,25.6 487.0,24.2 498.0,22.8 509.0,21.4 520.0,20.0\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"4\"/><polyline points=\"80.0,130.0 91.0,147.4 102.0,154.6 113.0,160.1 124.0,164.8 135.0,168.9 146.0,172.6 157.0,176.0 168.0,179.2 179.0,182.2 190.0,185.0 201.0,187.7 212.0,190.2 223.0,192.7 234.0,195.1 245.0,197.4 256.0,199.6 267.0,201.7 278.0,203.8 289.0,205.8 300.0,207.8 311.0,209.7 322.0,211.6 333.0,213.4 344.0,215.2 355.0,217.0 366.0,218.7 377.0,220.4 388.0,222.0 399.0,223.7 410.0,225.3 421.0,226.8 432.0,228.4 443.0,229.9 454.0,231.4 465.0,232.9 476.0,234.4 487.0,235.8 498.0,237.2 509.0,238.6 520.0,240.0\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"3\" stroke-dasharray=\"7 5\"/><ellipse cx=\"520\" cy=\"130\" rx=\"24\" ry=\"110\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"3\"/><ellipse cx=\"322\" cy=\"130\" rx=\"16\" ry=\"81.6\" fill=\"#f5d56e\" fill-opacity=\"0.5\" stroke=\"var(--red)\" stroke-width=\"4\"/><line x1=\"322\" y1=\"130\" x2=\"322\" y2=\"48.4\" stroke=\"var(--red)\" stroke-width=\"4\"/><text x=\"300\" y=\"98\" text-anchor=\"end\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:28px;fill:var(--red)\">f<tspan style=\"font-family:KaTeX_Main,serif;font-style:normal\">(</tspan>x<tspan style=\"font-family:KaTeX_Main,serif;font-style:normal\">)</tspan></text><text x=\"322\" y=\"265\" text-anchor=\"middle\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:28px;fill:var(--ink)\">x</text><text x=\"590\" y=\"120\" text-anchor=\"end\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:28px;fill:var(--ink)\">x</text><text x=\"140\" y=\"40\" text-anchor=\"middle\" style=\"font-family:inherit;font-size:24px;fill:var(--ink)\">一片圓盤</text><line x1=\"190\" y1=\"46\" x2=\"312\" y2=\"58\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/></svg>"},{"do":"write","line":"　每一片是半徑 $f(x)$、厚 $dx$ 的薄圓柱：$\\pi f(x)^2\\,dx$","color":"violet","on":"of"}],"t":[123950,136050]}]},{"title":"例：$y=\\sqrt x$ 繞 $x$ 軸","beats":[{"show":["$y=\\sqrt x$，$0\\le x\\le4$，與 $x$ 軸之間的區域繞 $x$ 軸"],"say":"例子：y 等於根號 x，x 從 0 到 4，跟 x 軸之間的區域，繞 x 軸旋轉，求體積。就是上一張圖的立體。","board":[{"do":"write","line":"$y=\\sqrt x$，$0\\le x\\le4$，與 $x$ 軸之間的區域繞 $x$ 軸"}],"t":[136050,147930]},{"show":["半徑 $f(x)=\\sqrt x$，截面 $A(x)=\\pi(\\sqrt x)^2=\\pi x$"],"say":"在 x 處切，半徑是根號 x，圓盤面積是派乘根號 x 的平方，也就是派 x。平方把根號消掉了。","board":[{"do":"write","line":"半徑 $f(x)=\\sqrt x$，截面 $A(x)=\\pi(\\sqrt x)^2=\\pi x$"}],"t":[147930,158360]},{"show":["$V=\\int_0^4\\pi x\\,dx=\\pi\\Big[\\frac{x^2}{2}\\Big]_0^4=8\\pi$"],"say":"從 0 積到 4：派乘 2 分之 x 平方，代 4 得 8。體積是 8 派。","board":[{"do":"write","line":"${{bx3:\\displaystyle V=\\int_0^4\\pi x\\,dx=\\pi\\Big[\\frac{x^2}{2}\\Big]_0^4=8\\pi}}$","color":"red"},{"do":"box","term":"bx3","color":"red","on":"平方"}],"t":[158360,167060]},{"show":["紅線轉一圈就是一片圓盤；虛線是轉過去的另一半"],"say":"圖上的紅線，是在 x 處的那一條。把它從左邊滑到右邊：每一條轉一圈都是一片圓盤，半徑越來越大。","board":[{"do":"plot","nb":{"spec":{"id":"sq","window":[-0.5,4.5,-2.5,2.5],"fn":[{"expr":"sqrt(x)","color":"blue","label":"y = √x","domain":[0,4]},{"expr":"-sqrt(x)","color":"blue","dash":true,"domain":[0,4]}],"area":[{"expr":"sqrt(x)","from":0,"to":4,"color":"blue"}],"lines":[{"from":["t",0],"to":["t","sqrt(t)"],"color":"red"}],"points":[{"x":"t","y":"sqrt(t)","color":"red"}],"params":{"t":{"min":0.2,"max":3.8,"value":1,"label":"x"}},"height":250}}},{"do":"write","line":"紅線轉一圈就是一片圓盤；虛線是轉過去的另一半","color":"violet","on":"到右"}],"t":[167060,181460]},{"show":["對照：外面套一個半徑 $2$、長 $4$ 的圓柱：$\\pi\\cdot2^2\\cdot4=16\\pi$"],"say":"對照一下：把它整個套進一個半徑 2、長 4 的圓柱，圓柱是 16 派。這個碗狀的立體剛好是它的一半。","board":[{"do":"plot","nb":{"spec":{"id":"sq","window":[-0.5,4.5,-2.5,2.5],"fn":[{"expr":"sqrt(x)","color":"blue","label":"y = √x","domain":[0,4]},{"expr":"-sqrt(x)","color":"blue","dash":true,"domain":[0,4]}],"area":[{"expr":"sqrt(x)","from":0,"to":4,"color":"blue"}],"lines":[{"from":["t",0],"to":["t","sqrt(t)"],"color":"red"}],"points":[{"x":"t","y":"sqrt(t)","color":"red"}],"params":{"t":{"min":0.2,"max":3.8,"value":1,"label":"x"}},"height":250},"vals":{"t":3.6}}},{"do":"write","line":"對照：外面套一個半徑 $2$、長 $4$ 的圓柱：$\\pi\\cdot2^2\\cdot4=16\\pi$","on":"的圓"},{"do":"write","line":"　拋物線轉出來的「碗」叫旋轉拋物面；體積是外接圓柱的一半","color":"violet","on":"這個"}],"t":[181460,193160]}]},{"title":"例：球的體積公式","beats":[{"show":["半圓 $y=\\sqrt{r^2-x^2}$，$-r\\le x\\le r$，繞 $x$ 軸 → 半徑 $r$ 的球"],"say":"再用圓盤法證明一個熟悉的公式：球的體積。上半圓 y 等於根號 r 平方減 x 平方，繞 x 軸轉一圈，就是半徑 r 的球。","board":[{"do":"write","line":"半圓 $y=\\sqrt{r^2-x^2}$，$-r\\le x\\le r$，繞 $x$ 軸 → 半徑 $r$ 的球"}],"t":[193160,205760]},{"show":["截面半徑 $\\sqrt{r^2-x^2}$：$A(x)=\\pi(r^2-x^2)$"],"say":"在 x 處切，半徑是根號 r 平方減 x 平方，面積是派乘 r 平方減 x 平方。","board":[{"do":"write","line":"截面半徑 $\\sqrt{r^2-x^2}$：$A(x)=\\pi(r^2-x^2)$"}],"t":[205760,214360]},{"show":["$V=\\pi\\Big[r^2x-\\frac{x^3}{3}\\Big]_{-r}^{r}=\\pi\\Big(2r^3-\\frac{2r^3}{3}\\Big)$"],"say":"積分：r 平方 x 減 3 分之 x 立方，從負 r 代到 r，得到 2 r 立方減 3 分之 2 r 立方。","board":[{"do":"write","line":"$\\displaystyle V=\\pi\\Big[r^2x-\\frac{x^3}{3}\\Big]_{-r}^{r}=\\pi\\Big(2r^3-\\frac{2r^3}{3}\\Big)$"}],"t":[214360,225760]},{"show":["$V=\\frac43\\pi r^3$"],"say":"就是 3 分之 4 派 r 立方。國中背的公式，現在證出來了。","board":[{"do":"write","line":"${{bx4:\\displaystyle V=\\frac43\\pi r^3}}$","color":"red"},{"do":"box","term":"bx4","color":"red","on":"國中"}],"t":[225760,233490]}],"check":0},{"title":"繞 y 軸：半徑換成 y","beats":[{"show":["區域：$y=x^2$（$0\\le x\\le1$）、$y$ 軸、$y=1$ 所圍，繞 $y$ 軸"],"say":"換成繞 y 軸。區域是 y 等於 x 平方、y 軸、跟 y 等於 1 圍起來的那一塊，在曲線的左上方。","board":[{"do":"write","line":"區域：$y=x^2$（$0\\le x\\le1$）、$y$ 軸、$y=1$ 所圍，繞 $y$ 軸"}],"t":[243100,253700]},{"show":["垂直 $y$ 軸切：水平的薄片，厚度是 $dy$"],"say":"繞 y 軸，就要垂直 y 軸來切，切出來是水平的薄片，厚度是 d y。所以要對 y 積分。","board":[{"do":"write","line":"垂直 $y$ 軸切：水平的薄片，厚度是 $dy$"}],"t":[253700,265180]},{"show":["半徑 = 到 $y$ 軸的距離 = $x$，寫成 $y$：$x=\\sqrt y$","$A(y)=\\pi(\\sqrt y)^2=\\pi y$"],"say":"半徑是曲線到 y 軸的距離，也就是 x。但我們對 y 積分，要把它寫成 y 的函數：x 等於根號 y。面積是派 y。","board":[{"do":"write","line":"半徑 = 到 $y$ 軸的距離 = $x$，寫成 $y$：$x=\\sqrt y$"},{"do":"write","line":"$\\displaystyle A(y)=\\pi(\\sqrt y)^2=\\pi y$","on":"要把"}],"t":[265180,277590]},{"show":["$V=\\int_0^1\\pi y\\,dy=\\frac{\\pi}{2}$"],"say":"y 從 0 積到 1，得到 2 分之派。","board":[{"do":"write","line":"${{bx5:\\displaystyle V=\\int_0^1\\pi y\\,dy=\\frac{\\pi}{2}}}$","color":"red"},{"do":"box","term":"bx5","color":"red","on":"得到"}],"t":[277590,282690]},{"show":["水平的紅線繞 y 軸一圈 = 半徑 √y 的圓盤"],"say":"圖上，紅色的水平線從 y 軸連到曲線，長度就是根號 y。往上滑，半徑變大。","board":[{"do":"plot","nb":{"spec":{"id":"yax","window":[-1.3,1.3,-0.2,1.3],"equal":true,"fn":[{"expr":"x^2","color":"blue","label":"y = x²","domain":[0,1.1]},{"expr":"x^2","color":"blue","dash":true,"domain":[-1.1,0]}],"area":[{"expr":"x^2","from":0,"to":1,"color":"blue","under":"1"}],"lines":[{"from":[0,"s"],"to":["sqrt(s)","s"],"color":"red"}],"points":[{"x":"sqrt(s)","y":"s","color":"red"}],"hlines":[{"y":1}],"params":{"s":{"min":0.05,"max":0.95,"value":0.3,"label":"y"}},"height":250}}},{"do":"write","line":"水平的紅線繞 y 軸一圈 = 半徑 √y 的圓盤","color":"violet","on":"長度"}],"t":[282690,296470]},{"show":["繞 $y$ 軸，$x=g(y)$：","$V=\\int_c^d\\pi\\,[g(y)]^2\\,dy$"],"say":"一般來說：繞 y 軸，邊界寫成 x 等於 g of y，體積是派乘 g of y 平方，對 y 從 c 積到 d。","board":[{"do":"plot","nb":{"spec":{"id":"yax","window":[-1.3,1.3,-0.2,1.3],"equal":true,"fn":[{"expr":"x^2","color":"blue","label":"y = x²","domain":[0,1.1]},{"expr":"x^2","color":"blue","dash":true,"domain":[-1.1,0]}],"area":[{"expr":"x^2","from":0,"to":1,"color":"blue","under":"1"}],"lines":[{"from":[0,"s"],"to":["sqrt(s)","s"],"color":"red"}],"points":[{"x":"sqrt(s)","y":"s","color":"red"}],"hlines":[{"y":1}],"params":{"s":{"min":0.05,"max":0.95,"value":0.3,"label":"y"}},"height":250},"vals":{"s":0.9}}},{"do":"write","line":"繞 $y$ 軸，$x=g(y)$：","on":"等於"},{"do":"write","line":"${{bx6:\\displaystyle V=\\int_c^d\\pi\\,[g(y)]^2\\,dy}}$","on":"體積"},{"do":"box","term":"bx6","on":"積到"}],"t":[296470,308970]}]},{"title":"試一題","beats":[{"show":["上一頁的區域（$y=x^2$、$y$ 軸、$y=1$）繞 $y$ 軸，哪個式子對？"],"say":"先自己判斷，哪一個式子才對？","t":[308970,318730]}],"check":1},{"title":"試一題","beats":[{"show":["口訣：片垂直於軸；對片的厚度方向積分"],"say":"記住一句話：片一定垂直於旋轉軸，厚度朝哪個方向，就對哪個變數積分。","board":[{"do":"write","line":"口訣：片垂直於軸；對片的厚度方向積分","color":"gold"}],"t":[318730,327410]},{"show":["如果改成 $y=x^2$ 下方（$x$ 軸、$x=1$）繞 $y$ 軸？"],"say":"想一想：如果換成曲線下方那一塊，繞 y 軸呢？","board":[{"do":"write","line":"如果改成 $y=x^2$ 下方（$x$ 軸、$x=1$）繞 $y$ 軸？"}],"t":[327410,333030]},{"show":["水平切片中間會空一段：截面是有洞的圓"],"say":"這時水平的切片，靠近 y 軸那一段是空的，轉起來中間有個洞，截面不再是實心的圓盤。這種情況下一課用墊圈法處理。","board":[{"do":"write","line":"水平切片中間會空一段：截面是有洞的圓","color":"red"},{"do":"write","line":"　下一課：$A=\\pi(R^2-r^2)$","color":"violet","on":"個洞"}],"t":[333030,346520]}]},{"title":"截面不是圓也可以","beats":[{"show":["底面是圓盤 $x^2+y^2\\le4$；垂直 $x$ 軸的截面都是正方形，一邊落在底面"],"say":"最後，截面不一定是圓。這個立體的底面是半徑 2 的圓盤；垂直 x 軸切下去，每個截面都是正方形，正方形的一邊躺在底面上。","board":[{"do":"write","line":"底面是圓盤 $x^2+y^2\\le4$；垂直 $x$ 軸的截面都是正方形，一邊落在底面"}],"t":[346520,362010]},{"show":["在 $x$ 處，底面的弦從 $y=-\\sqrt{4-x^2}$ 到 $\\sqrt{4-x^2}$：","$s=2\\sqrt{4-x^2}$"],"say":"在 x 處，那一邊是底面圓上的一條弦，從負根號 4 減 x 平方，到正根號 4 減 x 平方，長度是 2 倍根號 4 減 x 平方。","board":[{"do":"write","line":"在 $x$ 處，底面的弦從 $y=-\\sqrt{4-x^2}$ 到 $\\sqrt{4-x^2}$："},{"do":"write","line":"$\\displaystyle s=2\\sqrt{4-x^2}$","on":"到正"}],"t":[362010,375610]},{"show":["$A(x)=s^2=4(4-x^2)$"],"say":"正方形面積是邊長平方，等於 4 乘 4 減 x 平方。","board":[{"do":"write","line":"$\\displaystyle A(x)=s^2=4(4-x^2)$"}],"t":[375610,381410]},{"show":["$V=\\int_{-2}^{2}4(4-x^2)\\,dx=4\\Big[4x-\\frac{x^3}{3}\\Big]_{-2}^{2}=\\frac{128}{3}$"],"say":"從負 2 積到 2：4x 減 3 分之 x 立方，代進去差是 3 分之 32，乘 4，體積是 3 分之 128。","board":[{"do":"write","line":"${{bx7:\\displaystyle V=\\int_{-2}^{2}4(4-x^2)\\,dx=4\\Big[4x-\\frac{x^3}{3}\\Big]_{-2}^{2}=\\frac{128}{3}}}$","color":"red"},{"do":"box","term":"bx7","color":"red","on":"差是"}],"t":[381410,393710]},{"show":["圖"],"say":"圖上，藍色是底面的圓。黃色的正方形站在一條弦上；越靠近中間，弦越長，正方形越大；越靠近邊緣越小。","board":[{"do":"plot","svg":"<svg viewBox=\"0 0 620 270\" width=\"620\"><polygon points=\"400.0,218.0 404.5,214.9 408.4,211.7 411.4,208.7 413.7,205.7 415.2,202.8 415.9,200.0 415.8,197.4 414.9,194.9 413.2,192.5 410.7,190.4 407.5,188.5 403.5,186.8 398.8,185.4 393.4,184.2 387.4,183.2 380.8,182.5 373.6,182.1 366.0,182.0 357.9,182.1 349.5,182.5 340.8,183.2 331.8,184.2 322.7,185.4 313.5,186.8 304.3,188.5 295.0,190.4 286.0,192.5 277.1,194.9 268.4,197.4 260.1,200.0 252.1,202.8 244.6,205.7 237.6,208.7 231.1,211.7 225.2,214.9 220.0,218.0 215.5,221.1 211.6,224.3 208.6,227.3 206.3,230.3 204.8,233.2 204.1,236.0 204.2,238.6 205.1,241.1 206.8,243.5 209.3,245.6 212.5,247.5 216.5,249.2 221.2,250.6 226.6,251.8 232.6,252.8 239.2,253.5 246.4,253.9 254.0,254.0 262.1,253.9 270.5,253.5 279.2,252.8 288.2,251.8 297.3,250.6 306.5,249.2 315.7,247.5 325.0,245.6 334.0,243.5 342.9,241.1 351.6,238.6 359.9,236.0 367.9,233.2 375.4,230.3 382.4,227.3 388.9,224.3 394.8,221.1\" fill=\"var(--blue)\" fill-opacity=\"0.1\" stroke=\"var(--blue)\" stroke-width=\"3\"/><line x1=\"170\" y1=\"218\" x2=\"450\" y2=\"218\" stroke=\"var(--muted)\" stroke-width=\"2\" stroke-dasharray=\"8 6\"/><polygon points=\"340.5,241.8 414.5,194.2 414.5,83.1 340.5,130.7\" fill=\"none\" stroke=\"var(--muted)\" stroke-width=\"2\"/><polygon points=\"283.6,252.3 390.4,183.7 390.4,23.4 283.6,92.1\" fill=\"#f5d56e\" fill-opacity=\"0.5\" stroke=\"var(--red)\" stroke-width=\"4\"/><text x=\"458\" y=\"226\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:28px;fill:var(--ink)\">x</text><text x=\"340\" y=\"150\" text-anchor=\"middle\" style=\"font-family:inherit;font-size:24px;fill:var(--red)\">正方形</text><text x=\"270\" y=\"180\" text-anchor=\"end\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:28px;fill:var(--red)\">s</text><text x=\"80\" y=\"200\" style=\"font-family:inherit;font-size:24px;fill:var(--blue)\">底：圓盤</text></svg>"},{"do":"write","line":"　想法跟圓盤法完全一樣：先找截面面積 $A(x)$，再積分","color":"violet","on":"越靠#1"}],"t":[393710,406820]}]},{"title":"試一題","beats":[{"show":["同一個底面 $x^2+y^2\\le4$，截面改成正三角形（一邊落在底面），體積是？"],"say":"換成正三角形，試試看。","t":[406820,421530]}],"check":2},{"title":"試一題","beats":[{"show":["步驟都一樣：","1. 決定切的方向（垂直哪一軸）"],"say":"不管截面是什麼形狀，步驟都一樣：決定切的方向，寫出截面面積，找出範圍，積分。","board":[{"do":"write","line":"步驟都一樣："},{"do":"write","line":"1. 決定切的方向（垂直哪一軸）","on":"步驟"},{"do":"write","line":"2. 寫出截面面積 $A(x)$","on":"的方"},{"do":"write","line":"3. 找出 $x$ 的範圍，積分","on":"找出"}],"t":[421530,438970]}]},{"title":"重點整理","beats":[{"show":["• 體積 = 截面面積的積分：$V=\\int_a^b A(x)\\,dx$","• 繞 $x$ 軸：$V=\\int_a^b\\pi f(x)^2\\,dx$（圓盤）"],"say":"整理一下：體積就是截面面積的積分。旋轉體的截面是圓盤；繞 y 軸，半徑寫成 y 的函數。截面是別的形狀，一樣先找面積。","board":[{"do":"write","line":"• 體積 = 截面面積的積分：$V=\\int_a^b A(x)\\,dx$"},{"do":"write","line":"• 繞 $x$ 軸：$V=\\int_a^b\\pi f(x)^2\\,dx$（圓盤）","on":"面積#1"},{"do":"write","line":"• 繞 $y$ 軸：半徑寫成 $y$ 的函數，$V=\\int_c^d\\pi g(y)^2\\,dy$","on":"是圓"},{"do":"write","line":"• 片垂直於軸，對厚度的方向積分","on":"寫成"},{"do":"write","line":"• 截面是正方形、三角形……：一樣先找 $A(x)$","on":"別的"}],"t":[438970,453080]},{"show":["下一課：墊圈法（中間有洞）"],"say":"下一課，處理中間有洞的情況：墊圈法。","board":[{"do":"write","line":"下一課：墊圈法（中間有洞）"}],"t":[453080,459833]}]}],"checks":[{"ask":"$y=x$（$0\\le x\\le2$）與 $x$ 軸之間的區域繞 $x$ 軸，體積是？","options":[{"label":"$\\dfrac{8\\pi}{3}$","correct":true},{"label":"$2\\pi$","why":"半徑要平方：你算的是 $\\int_0^2\\pi x\\,dx$"},{"label":"$8\\pi$","why":"半徑不是一路都是 $2$；那是外接圓柱 $\\pi\\cdot2^2\\cdot2$"},{"label":"$\\dfrac83$","why":"少了 $\\pi$：截面是圓，面積是 $\\pi r^2$"}]},{"ask":"上一頁的區域（$y=x^2$、$y$ 軸、$y=1$）繞 $y$ 軸，哪個式子對？","options":[{"label":"$\\displaystyle\\int_0^1\\pi y\\,dy$","correct":true},{"label":"$\\displaystyle\\int_0^1\\pi x^4\\,dx$","why":"這是 $y=x^2$ 下方繞 ==$x$ 軸==的式子，軸弄錯了"},{"label":"$\\displaystyle\\int_0^1\\pi y^2\\,dy$","why":"半徑是到 $y$ 軸的距離 $x=\\sqrt y$，不是 $y$"},{"label":"$\\displaystyle\\int_0^1\\pi x^2\\,dx$","why":"片是水平的、厚度是 $dy$；積分變數要跟著片的厚度"}]},{"ask":"同一個底面 $x^2+y^2\\le4$，截面改成==正三角形==（一邊落在底面），體積是？","options":[{"label":"$\\dfrac{32\\sqrt3}{3}$","correct":true},{"label":"$\\dfrac{128}{3}$","why":"那是正方形；正三角形面積是 $\\frac{\\sqrt3}4s^2$，不是 $s^2$"},{"label":"$\\dfrac{8\\sqrt3}{3}$","why":"邊長忘了乘 $2$：弦長是 $2\\sqrt{4-x^2}$"},{"label":"$\\dfrac{16\\sqrt3}{3}$","why":"只積了 $0$ 到 $2$；底面從 $-2$ 到 $2$"}]}],"practice":[{"id":"lec-09-m2","core":true},{"id":"tb-rev-003","core":true},{"id":"tb-rev-001","core":true},{"id":"cx-rev-002","core":true},{"id":"lec-09-q4b","core":true},{"id":"cg-5b-001","core":true},{"id":"cg-5b-004","core":true},{"id":"tb-rev-002"},{"id":"cx-rev-006"},{"id":"cx-rev-007"},{"id":"lec-09-q2a"},{"id":"lec-09-q4c"},{"id":"cx-rev-004"},{"id":"cg-5b-002"},{"id":"cg-5b-005"},{"id":"cg-5b-003"}]},"volume-washer":{"id":"volume-washer","prerequisites":["volume-disk","area-between-curves"],"next":["volume-shell"],"related":[],"objectives":["旋轉區域中間有空隙時，截面是墊圈：$A=\\pi(R^2-r^2)$","外半徑、內半徑都是「到旋轉軸的距離」，會在軸不是座標軸時正確算出來","繞 $y$ 軸時改成對 $y$ 積分，外內半徑寫成 $y$ 的函數"],"concept":[{"heading":"① 中間有洞：墊圈","body":["上一課的區域都貼著旋轉軸：截面是實心圓盤","如果區域和軸之間有空隙，轉起來中間就有洞","截面是一個墊圈：外半徑 $R$、內半徑 $r$","墊圈：螺絲底下那個中間有洞的金屬片"],"tex":["A=\\pi R^2-\\pi r^2=\\pi\\,(R^2-r^2)","V=\\int_a^b\\pi\\,\\big(R(x)^2-r(x)^2\\big)\\,dx"]},{"heading":"① 先猜猜看","body":["常見錯誤：寫成 $\\pi(R-r)^2$","例：$9-4=5$，但 $(3-2)^2=1$","口訣：先平方，再相減"],"tex":["R^2-r^2\\ne(R-r)^2"]},{"heading":"① 例：$y=x$、$y=x^2$ 繞 $x$ 軸","body":["交點：$x=x^2\\Rightarrow x=0,\\ 1$；在 $(0,1)$ 上 $x>x^2$","在 $x$ 處垂直切：線段從 $y=x^2$ 到 $y=x$","外半徑 $R=x$，內半徑 $r=x^2$","也可以看成：大立體（$y=x$ 轉）減小立體（$y=x^2$ 轉）"],"tex":["V=\\int_0^1\\pi\\,(x^2-x^4)\\,dx=\\pi\\Big(\\frac13-\\frac15\\Big)=\\frac{2\\pi}{15}"]},{"heading":"② 半徑是「到軸的距離」","body":["$R$、$r$ 不是「$y$ 值」，是到旋轉軸的距離","繞水平線 $y=k$：點 $(x,y)$ 到軸的距離 $=|y-k|$","• 軸在區域上方：距離 $=k-y$","• 軸在區域下方：距離 $=y-k$","例：$R$：$y=2x-x^2$ 與 $x$ 軸所圍，繞直線 $y=1$","$2x-x^2=0\\Rightarrow x=0,2$；頂點 $(1,1)$ 剛好碰到軸","在 $x$ 處：線段從 $y=0$ 到 $y=2x-x^2$，軸在上方","• 下端 $y=0$ 離軸遠：$R=1-0=1$","• 上端離軸近：$r=1-(2x-x^2)=(1-x)^2$"]},{"heading":"② 例：繞 $y=1$","body":["其中"],"tex":["A(x)=\\pi\\big(1^2-(1-x)^4\\big)","V=\\pi\\int_0^2\\big(1-(1-x)^4\\big)\\,dx","\\int_0^2(1-x)^4dx=\\Big[-\\frac{(1-x)^5}{5}\\Big]_0^2","=\\frac15+\\frac15=\\frac25","V=\\pi\\Big(2-\\frac25\\Big)=\\frac{8\\pi}{5}"]},{"heading":"② 試一題","body":["答案積出來：","檢查：外半徑一定 $\\ge$ 內半徑；積出負數就是內外顛倒"],"tex":["\\pi\\int_0^1(2x-x^2-x^4)\\,dx=\\frac{7\\pi}{15}"]},{"heading":"③ 繞 y 軸：對 y 積分","body":["同一個區域（$y=x$、$y=x^2$）繞 $y$ 軸","片要垂直 $y$ 軸：水平切，厚度 $dy$，$y$ 從 $0$ 到 $1$","邊界寫成 $x=$：$y=x\\Rightarrow x=y$；$y=x^2\\Rightarrow x=\\sqrt y$","$0<y<1$ 時 $\\sqrt y>y$：$R=\\sqrt y$，$r=y$","跟繞 $x$ 軸時相反：這次拋物線在外"],"tex":["V=\\int_0^1\\pi\\,(y-y^2)\\,dy=\\pi\\Big(\\frac12-\\frac13\\Big)=\\frac{\\pi}{6}"]},{"heading":"③ 試一題：繞 x = −1","body":["繞鉛直線 $x=h$：距離 $=|x-h|$，$x$ 用 $y$ 表示","• 繞 $x$ 軸或 $y=k$：垂直切，對 $x$ 積分","• 繞 $y$ 軸或 $x=h$：水平切，對 $y$ 積分"]},{"heading":"④ 圓盤是墊圈的特例","body":["區域貼著軸時，內半徑 $r=0$：","所以只要記一個公式：$\\pi(R^2-r^2)$","例：上一課 $y=\\sqrt x$ 繞 $x$ 軸：$R=\\sqrt x$，$r=0$","一個區域也可能「有些地方有洞、有些地方沒有」：照樣寫 $R$、$r$，$r$ 是 $0$ 的地方就是 $0$"],"tex":["\\pi(R^2-0^2)=\\pi R^2"]},{"heading":"重點整理","body":["• 墊圈：$A=\\pi(R^2-r^2)$，先平方再相減","• $R$、$r$ 是到旋轉軸的距離，不是 $y$ 值","• 軸在 $y=k$：距離 $\\lvert y-k\\rvert$；軸在 $x=h$：距離 $\\lvert x-h\\rvert$","• 繞鉛直的軸：水平切，對 $y$ 積分","• 圓盤：$r=0$ 的墊圈","下一課：圓殼法（換個方向切）"]}],"workedExamples":[{"title":"繞 $x$ 軸","prompt":"$y=x$ 與 $y=x^2$ 所圍區域繞 $x$ 軸旋轉，求體積。","problemId":"cx-rev-003","steps":["交點 $x=0$、1。代 $x=\\frac{1}{2}$：$x=\\frac{1}{2}>\\frac{1}{4}=x^2$，$y=x$ 離 $x$ 軸較遠。","$R=x$，$r=x^2$。$A(x)=\\pi(x^2-x^4)$。","$V=\\pi\\int_0^1(x^2-x^4)\\,dx=\\pi\\left(\\frac{1}{3}-\\frac{1}{5}\\right)=\\frac{2\\pi}{15}$。"],"answer":"$\\frac{2\\pi}{15}$"},{"title":"繞水平線 $y=1$","prompt":"區域 $R$ 由 $y=2x-x^2$ 與 $x$ 軸圍成，繞直線 $y=1$ 旋轉，求體積。","problemId":"lec-09-q2d","steps":["區域是 $0\\le x\\le 2$，曲線最高點 $(1,1)$ 剛好碰到軸，整個區域在 $y=1$ 下方。","從軸往下量：$x$ 軸（$y=0$）到軸的距離是 1，比較遠，$R=1$；曲線到軸的距離是 $1-(2x-x^2)=(1-x)^2$，$r=(1-x)^2$。","$V=\\pi\\int_0^2(1^2-(1-x)^4)\\,dx$。令 $u=1-x$，$\\int_0^2(1-x)^4\\,dx=\\int_{-1}^1 u^4\\,du=\\frac{2}{5}$。","$V=\\pi\\left(2-\\frac{2}{5}\\right)=\\frac{8\\pi}{5}$。"],"answer":"$\\frac{8\\pi}{5}$"},{"title":"繞 $y$ 軸，對 $y$ 積分","prompt":"$y=x$ 與 $y=x^2$ 所圍區域繞 $y$ 軸旋轉，求體積。","steps":["水平切，$y$ 從 0 到 1。把兩條邊界寫成 $x$：直線 $x=y$，拋物線 $x=\\sqrt{y}$。","代 $y=\\frac{1}{4}$：$\\sqrt{y}=\\frac{1}{2}>\\frac{1}{4}=y$，拋物線離 $y$ 軸較遠。$R=\\sqrt{y}$，$r=y$。","$V=\\pi\\int_0^1((\\sqrt{y})^2-y^2)\\,dy=\\pi\\int_0^1(y-y^2)\\,dy=\\pi\\left(\\frac{1}{2}-\\frac{1}{3}\\right)=\\frac{\\pi}{6}$。"],"answer":"$\\frac{\\pi}{6}$"}],"pitfalls":["寫成 $\\pi(R-r)^2$：要先各自平方再相減。","外內半徑弄反，得到負的體積。","軸是 $y=1$ 時，半徑還直接用 $y$ 值，沒有換成到軸的距離。","繞 $y$ 軸時還在用 $x$ 當積分變數。"],"voice":"118a94fe","sections":[{"title":"中間有洞：墊圈","beats":[{"show":["上一課的區域都貼著旋轉軸：截面是實心圓盤"],"say":"上一課的區域，都是貼著旋轉軸的，所以切出來是實心的圓盤。","board":[{"do":"write","line":"上一課的區域都貼著旋轉軸：截面是實心圓盤"}],"t":[2980,9890]},{"show":["如果區域和軸之間有空隙，轉起來中間就有洞"],"say":"如果區域跟旋轉軸之間隔了一段空隙，轉一圈之後，中間就會有一個洞。","board":[{"do":"write","line":"如果區域和軸之間有空隙，轉起來中間就有洞"}],"t":[9890,19110]},{"show":["截面是一個墊圈：外半徑 $R$、內半徑 $r$","$A=\\pi R^2-\\pi r^2=\\pi\\,(R^2-r^2)$"],"say":"這時截面像一個墊圈：外圈半徑大 R，內圈半徑小 r。面積就是大圓盤減掉小圓盤，派乘 R 平方減 r 平方。","board":[{"do":"write","line":"截面是一個墊圈：外半徑 $R$、內半徑 $r$"},{"do":"write","line":"${{bx1:\\displaystyle A=\\pi R^2-\\pi r^2=\\pi\\,(R^2-r^2)}}$","color":"red","on":"內圈"},{"do":"box","term":"bx1","color":"red","on":"小圓"}],"t":[19110,30490]},{"show":["$V=\\int_a^b\\pi\\,\\big(R(x)^2-r(x)^2\\big)\\,dx$"],"say":"代進體積等於截面面積的積分，就是墊圈法。","board":[{"do":"write","line":"${{bx2:\\displaystyle V=\\int_a^b\\pi\\,\\big(R(x)^2-r(x)^2\\big)\\,dx}}$"},{"do":"box","term":"bx2","on":"的積"}],"t":[30490,36290]},{"show":["圖"],"say":"從軸的方向看過去，截面長這樣：黃色的環。紅色是外半徑，綠色是內半徑，中間是空的。","board":[{"do":"plot","svg":"<svg viewBox=\"0 0 620 250\" width=\"620\"><path d=\"M 310 20 A 105 105 0 1 1 309.9 20 Z M 310 75 A 50 50 0 1 0 310.1 75 Z\" fill=\"#f5d56e\" fill-opacity=\"0.6\" fill-rule=\"evenodd\" stroke=\"var(--blue)\" stroke-width=\"3\"/><circle cx=\"310\" cy=\"125\" r=\"4\" fill=\"var(--ink)\"/><line x1=\"310\" y1=\"125\" x2=\"384.2\" y2=\"50.8\" stroke=\"var(--red)\" stroke-width=\"3\"/><line x1=\"310\" y1=\"125\" x2=\"260\" y2=\"125\" stroke=\"var(--green)\" stroke-width=\"3\"/><text x=\"362\" y=\"104\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:30px;fill:var(--red)\">R</text><text x=\"285\" y=\"155\" text-anchor=\"middle\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:30px;fill:var(--green)\">r</text><text x=\"440\" y=\"200\" style=\"font-family:inherit;font-size:24px;fill:var(--ink)\">中間是空的</text><line x1=\"436\" y1=\"192\" x2=\"330\" y2=\"140\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/></svg>"},{"do":"write","line":"　墊圈：螺絲底下那個中間有洞的金屬片","color":"violet","on":"紅色"}],"t":[36290,47510]}]},{"title":"先猜猜看","beats":[{"show":["外半徑 $R=3$、內半徑 $r=2$ 的墊圈，面積是？"],"say":"先猜猜看：外半徑 3、內半徑 2 的墊圈，面積多少？","t":[47510,57220]}],"predict":{"ask":"外半徑 $R=3$、內半徑 $r=2$ 的墊圈，面積是？","options":[{"label":"$5\\pi$","correct":true},{"label":"$\\pi$","why":"這是 $\\pi(R-r)^2$：先減再平方，不等於 $R^2-r^2$"},{"label":"$13\\pi$","why":"$R^2+r^2$：洞要減掉，不是加上"}]}},{"title":"先猜猜看","beats":[{"show":["常見錯誤：寫成 $\\pi(R-r)^2$"],"say":"最常見的錯，是把面積寫成派乘 R 減 r 的平方。","board":[{"do":"write","line":"常見錯誤：寫成 $\\pi(R-r)^2$","color":"red"}],"t":[57220,62620]},{"show":["$R^2-r^2\\ne(R-r)^2$"],"say":"先減再平方，算的是一個寬度為 R 減 r 的實心圓，不是環。一定是各自平方以後再相減。","board":[{"do":"write","line":"${{bx3:\\displaystyle R^2-r^2\\ne(R-r)^2}}$"},{"do":"box","term":"bx3","on":"的實"},{"do":"write","line":"　例：$9-4=5$，但 $(3-2)^2=1$","color":"violet","on":"一定"}],"t":[62620,72270]},{"show":["口訣：先平方，再相減"],"say":"記一句話：先平方，再相減。","board":[{"do":"write","line":"口訣：先平方，再相減"}],"t":[72270,77240]}]},{"title":"例：$y=x$、$y=x^2$ 繞 $x$ 軸","beats":[{"show":["交點：$x=x^2\\Rightarrow x=0,\\ 1$；在 $(0,1)$ 上 $x>x^2$"],"say":"例子：y 等於 x 跟 y 等於 x 平方圍成的區域，繞 x 軸。先找交點，x 等於 0 和 1。中間這一段，直線在拋物線上面。","board":[{"do":"write","line":"交點：$x=x^2\\Rightarrow x=0,\\ 1$；在 $(0,1)$ 上 $x>x^2$"}],"t":[77240,90780]},{"show":["在 $x$ 處垂直切：線段從 $y=x^2$ 到 $y=x$"],"say":"在 x 處垂直切一刀，這條線段的下端在拋物線上，上端在直線上。它沒有碰到 x 軸。","board":[{"do":"write","line":"在 $x$ 處垂直切：線段從 $y=x^2$ 到 $y=x$"}],"t":[90780,100270]},{"show":["外半徑 $R=x$，內半徑 $r=x^2$"],"say":"轉一圈，離軸比較遠的上端畫出外圈，半徑 x；比較近的下端畫出內圈，半徑 x 平方。","board":[{"do":"write","line":"外半徑 $R=x$，內半徑 $r=x^2$"}],"t":[100270,109680]},{"show":["$V=\\int_0^1\\pi\\,(x^2-x^4)\\,dx=\\pi\\Big(\\frac13-\\frac15\\Big)=\\frac{2\\pi}{15}$"],"say":"積分：x 平方減 x 的四次方，從 0 積到 1，得到 3 分之 1 減 5 分之 1，體積是 15 分之 2 派。","board":[{"do":"write","line":"${{bx4:\\displaystyle V=\\int_0^1\\pi\\,(x^2-x^4)\\,dx=\\pi\\Big(\\frac13-\\frac15\\Big)=\\frac{2\\pi}{15}}}$","color":"red"},{"do":"box","term":"bx4","color":"red","on":"分之#1"}],"t":[109680,122380]},{"show":["紅色線段轉一圈 = 墊圈；它和 x 軸之間的空隙就是洞"],"say":"圖上，紅色線段和 x 軸之間隔著一段灰色虛線。那段空隙轉一圈，就是墊圈中間的洞。","board":[{"do":"plot","nb":{"spec":{"id":"wx","window":[-0.2,1.3,-1.1,1.2],"fn":[{"expr":"x","color":"blue","label":"y = x","domain":[0,1.15]},{"expr":"x^2","color":"green","label":"y = x²","domain":[0,1.05]},{"expr":"-x","color":"blue","dash":true,"domain":[0,1]},{"expr":"-x^2","color":"green","dash":true,"domain":[0,1]}],"area":[{"expr":"x","from":0,"to":1,"color":"blue","under":"x^2"}],"lines":[{"from":["t","t^2"],"to":["t","t"],"color":"red"},{"from":["t",0],"to":["t","t^2"],"color":"pencil","dash":true}],"params":{"t":{"min":0.1,"max":0.95,"value":0.6,"label":"x"}},"height":260}}},{"do":"write","line":"紅色線段轉一圈 = 墊圈；它和 x 軸之間的空隙就是洞","color":"violet","on":"軸之"},{"do":"plot","nb":{"spec":{"id":"wx","window":[-0.2,1.3,-1.1,1.2],"fn":[{"expr":"x","color":"blue","label":"y = x","domain":[0,1.15]},{"expr":"x^2","color":"green","label":"y = x²","domain":[0,1.05]},{"expr":"-x","color":"blue","dash":true,"domain":[0,1]},{"expr":"-x^2","color":"green","dash":true,"domain":[0,1]}],"area":[{"expr":"x","from":0,"to":1,"color":"blue","under":"x^2"}],"lines":[{"from":["t","t^2"],"to":["t","t"],"color":"red"},{"from":["t",0],"to":["t","t^2"],"color":"pencil","dash":true}],"params":{"t":{"min":0.1,"max":0.95,"value":0.6,"label":"x"}},"height":260},"vals":{"t":0.3}},"on":"虛線"},{"do":"write","line":"　也可以看成：大立體（$y=x$ 轉）減小立體（$y=x^2$ 轉）","color":"violet","on":"就是"}],"t":[122380,135720]}]},{"title":"半徑是「到軸的距離」","beats":[{"show":["$R$、$r$ 不是「$y$ 值」，是到旋轉軸的距離"],"say":"墊圈法最容易錯的地方：外半徑、內半徑，不是 y 值，而是到旋轉軸的距離。軸剛好是 x 軸的時候，兩個才一樣。","board":[{"do":"write","line":"$R$、$r$ 不是「$y$ 值」，是到旋轉軸的距離","color":"red"}],"t":[135720,151730]},{"show":["繞水平線 $y=k$：點 $(x,y)$ 到軸的距離 $=|y-k|$","• 軸在區域上方：距離 $=k-y$"],"say":"繞水平線 y 等於 k，點到軸的距離是 y 減 k 的絕對值。軸在上方，就是 k 減 y；軸在下方，就是 y 減 k。","board":[{"do":"write","line":"繞水平線 $y=k$：點 $(x,y)$ 到軸的距離 $=|y-k|$"},{"do":"write","line":"• 軸在區域上方：距離 $=k-y$","on":"的絕"},{"do":"write","line":"• 軸在區域下方：距離 $=y-k$","on":"軸在#2"}],"t":[151730,164630]},{"show":["例：$R$：$y=2x-x^2$ 與 $x$ 軸所圍，繞直線 $y=1$"],"say":"例子：y 等於 2x 減 x 平方跟 x 軸圍成的區域，繞水平線 y 等於 1。","board":[{"do":"write","line":"例：$R$：$y=2x-x^2$ 與 $x$ 軸所圍，繞直線 $y=1$"}],"t":[164630,173030]},{"show":["$2x-x^2=0\\Rightarrow x=0,2$；頂點 $(1,1)$ 剛好碰到軸"],"say":"這條拋物線跟 x 軸交在 0 和 2，頂點在 1 逗號 1，剛好碰到旋轉軸。整個區域在軸的下方。","board":[{"do":"write","line":"$2x-x^2=0\\Rightarrow x=0,2$；頂點 $(1,1)$ 剛好碰到軸"}],"t":[173030,183030]},{"show":["在 $x$ 處：線段從 $y=0$ 到 $y=2x-x^2$，軸在上方"],"say":"在 x 處切一刀，線段從 x 軸到拋物線，旋轉軸在它上面。","board":[{"do":"write","line":"在 $x$ 處：線段從 $y=0$ 到 $y=2x-x^2$，軸在上方"}],"t":[183030,191440]},{"show":["• 下端 $y=0$ 離軸遠：$R=1-0=1$","• 上端離軸近：$r=1-(2x-x^2)=(1-x)^2$"],"say":"下端在 x 軸上，離軸比較遠，外半徑是 1 減 0 等於 1。上端離軸比較近，內半徑是 1 減 2x 加 x 平方，整理成 1 減 x 的平方。","board":[{"do":"write","line":"• 下端 $y=0$ 離軸遠：$R=1-0=1$"},{"do":"write","line":"• 上端離軸近：$r=1-(2x-x^2)=(1-x)^2$","on":"較近"}],"t":[191440,206940]}]},{"title":"例：繞 $y=1$","beats":[{"show":["$A(x)=\\pi\\big(1^2-(1-x)^4\\big)$"],"say":"截面面積：派乘 1 的平方減 1 減 x 的四次方。","board":[{"do":"write","line":"$\\displaystyle A(x)=\\pi\\big(1^2-(1-x)^4\\big)$"}],"t":[206940,212540]},{"show":["$V=\\pi\\int_0^2\\big(1-(1-x)^4\\big)\\,dx$"],"say":"從 0 積到 2。","board":[{"do":"write","line":"$\\displaystyle V=\\pi\\int_0^2\\big(1-(1-x)^4\\big)\\,dx$"}],"t":[212540,218150]},{"show":["其中","$\\int_0^2(1-x)^4dx=\\Big[-\\frac{(1-x)^5}{5}\\Big]_0^2$"],"say":"1 減 x 的四次方，反導函數是負的 5 分之 1 減 x 的五次方。代 2 得 5 分之 1，減掉代 0 的負 5 分之 1，合起來 5 分之 2。","board":[{"do":"write","line":"其中"},{"do":"write","line":"$\\displaystyle \\int_0^2(1-x)^4dx=\\Big[-\\frac{(1-x)^5}{5}\\Big]_0^2$","on":"的五"},{"do":"write","line":"$\\displaystyle =\\frac15+\\frac15=\\frac25$","on":"的負"}],"t":[218150,233550]},{"show":["$V=\\pi\\Big(2-\\frac25\\Big)=\\frac{8\\pi}{5}$"],"say":"所以體積是派乘 2 減 5 分之 2，等於 5 分之 8 派。","board":[{"do":"write","line":"${{bx5:\\displaystyle V=\\pi\\Big(2-\\frac25\\Big)=\\frac{8\\pi}{5}}}$","color":"red"},{"do":"box","term":"bx5","color":"red","on":"等於"}],"t":[233550,240850]},{"show":["虛線曲線是區域對 y = 1 翻上去的樣子"],"say":"圖上，紅色線段到軸之間還有一段空隙，那就是內半徑。滑到中間，空隙縮成 0；兩邊空隙大，洞也大。","board":[{"do":"plot","nb":{"spec":{"id":"wk","window":[-0.3,2.3,-0.3,2.3],"fn":[{"expr":"2*x-x^2","color":"blue","label":"y = 2x − x²","domain":[0,2]},{"expr":"2-(2*x-x^2)","color":"blue","dash":true,"domain":[0,2]}],"area":[{"expr":"2*x-x^2","from":0,"to":2,"color":"blue"}],"hlines":[{"y":1,"label":"y = 1","color":"red"}],"lines":[{"from":["t",0],"to":["t","2*t-t^2"],"color":"red"},{"from":["t","2*t-t^2"],"to":["t",1],"color":"pencil","dash":true}],"params":{"t":{"min":0.1,"max":1.9,"value":0.5,"label":"x"}},"height":260}}},{"do":"write","line":"虛線曲線是區域對 y = 1 翻上去的樣子","color":"violet","on":"還有"},{"do":"plot","nb":{"spec":{"id":"wk","window":[-0.3,2.3,-0.3,2.3],"fn":[{"expr":"2*x-x^2","color":"blue","label":"y = 2x − x²","domain":[0,2]},{"expr":"2-(2*x-x^2)","color":"blue","dash":true,"domain":[0,2]}],"area":[{"expr":"2*x-x^2","from":0,"to":2,"color":"blue"}],"hlines":[{"y":1,"label":"y = 1","color":"red"}],"lines":[{"from":["t",0],"to":["t","2*t-t^2"],"color":"red"},{"from":["t","2*t-t^2"],"to":["t",1],"color":"pencil","dash":true}],"params":{"t":{"min":0.1,"max":1.9,"value":0.5,"label":"x"}},"height":260},"vals":{"t":1}},"on":"滑到"},{"do":"plot","nb":{"spec":{"id":"wk","window":[-0.3,2.3,-0.3,2.3],"fn":[{"expr":"2*x-x^2","color":"blue","label":"y = 2x − x²","domain":[0,2]},{"expr":"2-(2*x-x^2)","color":"blue","dash":true,"domain":[0,2]}],"area":[{"expr":"2*x-x^2","from":0,"to":2,"color":"blue"}],"hlines":[{"y":1,"label":"y = 1","color":"red"}],"lines":[{"from":["t",0],"to":["t","2*t-t^2"],"color":"red"},{"from":["t","2*t-t^2"],"to":["t",1],"color":"pencil","dash":true}],"params":{"t":{"min":0.1,"max":1.9,"value":0.5,"label":"x"}},"height":260},"vals":{"t":1.8}},"on":"兩邊"}],"t":[240850,258060]}]},{"title":"試一題","beats":[{"show":["$y=x$、$y=x^2$ 所圍區域繞直線 $y=-1$，體積的式子是？"],"say":"試一題：同一個區域，改繞 y 等於負 1。","t":[258060,270760]}],"check":0},{"title":"試一題","beats":[{"show":["答案積出來：","$\\pi\\int_0^1(2x-x^2-x^4)\\,dx=\\frac{7\\pi}{15}$"],"say":"展開以後是 2x 減 x 平方減 x 四次方，積出來 15 分之 7 派。比繞 x 軸的 15 分之 2 派大很多，因為離軸更遠了。","board":[{"do":"write","line":"答案積出來："},{"do":"write","line":"${{bx6:\\displaystyle \\pi\\int_0^1(2x-x^2-x^4)\\,dx=\\frac{7\\pi}{15}}}$","on":"四次"},{"do":"box","term":"bx6","on":"比繞"},{"do":"write","line":"　檢查：外半徑一定 $\\ge$ 內半徑；積出負數就是內外顛倒","color":"violet","on":"派大"}],"t":[270760,285060]}]},{"title":"繞 y 軸：對 y 積分","beats":[{"show":["同一個區域（$y=x$、$y=x^2$）繞 $y$ 軸"],"say":"同一個區域，換成繞 y 軸。","board":[{"do":"write","line":"同一個區域（$y=x$、$y=x^2$）繞 $y$ 軸"}],"t":[285060,288950]},{"show":["片要垂直 $y$ 軸：水平切，厚度 $dy$，$y$ 從 $0$ 到 $1$"],"say":"片要垂直於旋轉軸，所以這次水平切，厚度是 d y，y 從 0 到 1。","board":[{"do":"write","line":"片要垂直 $y$ 軸：水平切，厚度 $dy$，$y$ 從 $0$ 到 $1$"}],"t":[288950,296350]},{"show":["邊界寫成 $x=$：$y=x\\Rightarrow x=y$；$y=x^2\\Rightarrow x=\\sqrt y$"],"say":"半徑是水平的距離，要用 y 表示。直線寫成 x 等於 y，拋物線寫成 x 等於根號 y。","board":[{"do":"write","line":"邊界寫成 $x=$：$y=x\\Rightarrow x=y$；$y=x^2\\Rightarrow x=\\sqrt y$"}],"t":[296350,305650]},{"show":["$0<y<1$ 時 $\\sqrt y>y$：$R=\\sqrt y$，$r=y$"],"say":"在 0 到 1 之間，根號 y 比 y 大，所以拋物線離 y 軸比較遠，是外半徑；直線是內半徑。","board":[{"do":"write","line":"$0<y<1$ 時 $\\sqrt y>y$：$R=\\sqrt y$，$r=y$"},{"do":"write","line":"　跟繞 $x$ 軸時相反：這次拋物線在外","color":"violet","on":"拋物"}],"t":[305650,315650]},{"show":["$V=\\int_0^1\\pi\\,(y-y^2)\\,dy=\\pi\\Big(\\frac12-\\frac13\\Big)=\\frac{\\pi}{6}$"],"say":"外半徑平方是 y，內半徑平方是 y 平方，積分得 2 分之 1 減 3 分之 1，體積是 6 分之派。","board":[{"do":"write","line":"${{bx7:\\displaystyle V=\\int_0^1\\pi\\,(y-y^2)\\,dy=\\pi\\Big(\\frac12-\\frac13\\Big)=\\frac{\\pi}{6}}}$","color":"red"},{"do":"box","term":"bx7","color":"red","on":"分之#1"}],"t":[315650,326950]},{"show":["水平的紅色線段繞 y 軸；左邊的空隙是洞"],"say":"圖上，水平的紅色線段從直線連到拋物線，左邊到 y 軸還隔著一段，就是洞。","board":[{"do":"plot","nb":{"spec":{"id":"wy","window":[-1.2,1.2,-0.15,1.15],"fn":[{"expr":"x","color":"blue","label":"y = x","domain":[0,1.1]},{"expr":"x^2","color":"green","label":"y = x²","domain":[0,1.05]},{"expr":"-x","color":"blue","dash":true,"domain":[-1,0]},{"expr":"x^2","color":"green","dash":true,"domain":[-1,0]}],"area":[{"expr":"x","from":0,"to":1,"color":"blue","under":"x^2"}],"lines":[{"from":["s","s"],"to":["sqrt(s)","s"],"color":"red"},{"from":[0,"s"],"to":["s","s"],"color":"pencil","dash":true}],"params":{"s":{"min":0.05,"max":0.95,"value":0.4,"label":"y"}},"height":260}}},{"do":"write","line":"水平的紅色線段繞 y 軸；左邊的空隙是洞","color":"violet","on":"線連"},{"do":"plot","nb":{"spec":{"id":"wy","window":[-1.2,1.2,-0.15,1.15],"fn":[{"expr":"x","color":"blue","label":"y = x","domain":[0,1.1]},{"expr":"x^2","color":"green","label":"y = x²","domain":[0,1.05]},{"expr":"-x","color":"blue","dash":true,"domain":[-1,0]},{"expr":"x^2","color":"green","dash":true,"domain":[-1,0]}],"area":[{"expr":"x","from":0,"to":1,"color":"blue","under":"x^2"}],"lines":[{"from":["s","s"],"to":["sqrt(s)","s"],"color":"red"},{"from":[0,"s"],"to":["s","s"],"color":"pencil","dash":true}],"params":{"s":{"min":0.05,"max":0.95,"value":0.4,"label":"y"}},"height":260},"vals":{"s":0.8}},"on":"軸還"}],"t":[326950,338850]}]},{"title":"試一題：繞 x = −1","beats":[{"show":["同一個區域繞鉛直線 $x=-1$，體積是？"],"say":"再試一題：繞鉛直線 x 等於負 1。到軸的距離，是 x 減負 1，也就是 x 加 1。","t":[338850,348830]}],"check":1},{"title":"試一題：繞 x = −1","beats":[{"show":["繞鉛直線 $x=h$：距離 $=|x-h|$，$x$ 用 $y$ 表示"],"say":"一般來說，繞鉛直線 x 等於 h，距離是 x 減 h 的絕對值，再把 x 換成 y 的函數。","board":[{"do":"write","line":"繞鉛直線 $x=h$：距離 $=|x-h|$，$x$ 用 $y$ 表示","color":"gold"}],"t":[348830,360300]},{"show":["• 繞 $x$ 軸或 $y=k$：垂直切，對 $x$ 積分","• 繞 $y$ 軸或 $x=h$：水平切，對 $y$ 積分"],"say":"整理一下：繞水平的軸，垂直切、對 x 積分；繞鉛直的軸，水平切、對 y 積分。","board":[{"do":"write","line":"• 繞 $x$ 軸或 $y=k$：垂直切，對 $x$ 積分"},{"do":"write","line":"• 繞 $y$ 軸或 $x=h$：水平切，對 $y$ 積分","on":"積分#1"}],"t":[360300,372200]}]},{"title":"圓盤是墊圈的特例","beats":[{"show":["區域貼著軸時，內半徑 $r=0$：","$\\pi(R^2-0^2)=\\pi R^2$"],"say":"最後，圓盤跟墊圈的關係：區域貼著軸的時候，內半徑是 0，墊圈公式就變成派 R 平方，正是圓盤。","board":[{"do":"write","line":"區域貼著軸時，內半徑 $r=0$："},{"do":"write","line":"${{bx8:\\displaystyle \\pi(R^2-0^2)=\\pi R^2}}$","on":"著軸"},{"do":"box","term":"bx8","on":"式就"}],"t":[372200,382900]},{"show":["所以只要記一個公式：$\\pi(R^2-r^2)$"],"say":"所以只要記一個公式，派乘 R 平方減 r 平方；沒有洞，就讓 r 等於 0。","board":[{"do":"write","line":"所以只要記一個公式：$\\pi(R^2-r^2)$"}],"t":[382900,390900]},{"show":["例：上一課 $y=\\sqrt x$ 繞 $x$ 軸：$R=\\sqrt x$，$r=0$"],"say":"例如上一課的根號 x 繞 x 軸，外半徑根號 x，內半徑 0，就回到圓盤法。","board":[{"do":"write","line":"例：上一課 $y=\\sqrt x$ 繞 $x$ 軸：$R=\\sqrt x$，$r=0$"},{"do":"write","line":"　一個區域也可能「有些地方有洞、有些地方沒有」：照樣寫 $R$、$r$，$r$ 是 $0$ 的地方就是 $0$","color":"violet","on":"徑根"}],"t":[390900,399600]}],"proof":true,"order":{"ask":"用墊圈法求體積的步驟","steps":[{"label":"畫出區域，找交點"},{"label":"片垂直於旋轉軸：決定對 $x$ 或對 $y$ 積分","why":"先要有上一步：畫出區域，找交點"},{"label":"寫出外半徑 $R$、內半徑 $r$（到軸的距離）","why":"先要有上一步：片垂直於旋轉軸：決定對 $x$ 或對 $y$ 積分"},{"label":"積分 $\\pi\\int(R^2-r^2)$","why":"先要有上一步：寫出外半徑 $R$、內半徑 $r$（到軸的距離）"}]}},{"title":"重點整理","beats":[{"show":["• 墊圈：$A=\\pi(R^2-r^2)$，先平方再相減","• $R$、$r$ 是到旋轉軸的距離，不是 $y$ 值"],"say":"整理一下：墊圈面積是派乘 R 平方減 r 平方，先平方再相減。半徑都是到旋轉軸的距離。繞鉛直的軸，就對 y 積分。圓盤只是內半徑為 0 的墊圈。","board":[{"do":"write","line":"• 墊圈：$A=\\pi(R^2-r^2)$，先平方再相減"},{"do":"write","line":"• $R$、$r$ 是到旋轉軸的距離，不是 $y$ 值","on":"平方#1"},{"do":"write","line":"• 軸在 $y=k$：距離 $\\lvert y-k\\rvert$；軸在 $x=h$：距離 $\\lvert x-h\\rvert$","on":"相減"},{"do":"write","line":"• 繞鉛直的軸：水平切，對 $y$ 積分","on":"繞鉛"},{"do":"write","line":"• 圓盤：$r=0$ 的墊圈","on":"圓盤"}],"t":[417440,433780]},{"show":["下一課：圓殼法（換個方向切）"],"say":"下一課，換一個方向切：圓殼法。","board":[{"do":"write","line":"下一課：圓殼法（換個方向切）"}],"t":[433780,439954]}]}],"checks":[{"ask":"$y=x$、$y=x^2$ 所圍區域繞直線 $y=-1$，體積的式子是？","options":[{"label":"$\\pi\\displaystyle\\int_0^1\\big[(x+1)^2-(x^2+1)^2\\big]dx$","correct":true},{"label":"$\\pi\\displaystyle\\int_0^1(x^2-x^4)\\,dx$","why":"這是繞 $x$ 軸；軸移到 $y=-1$，每個距離都要加 $1$"},{"label":"$\\pi\\displaystyle\\int_0^1\\big[(x^2+1)^2-(x+1)^2\\big]dx$","why":"內外顛倒：上面的 $y=x$ 離 $y=-1$ 比較遠"},{"label":"$\\pi\\displaystyle\\int_0^1\\big[(x+1)-(x^2+1)\\big]^2dx$","why":"先減再平方了：要 $R^2-r^2$"}]},{"ask":"同一個區域繞==鉛直線== $x=-1$，體積是？","options":[{"label":"$\\dfrac{\\pi}{2}$","correct":true},{"label":"$\\dfrac{\\pi}{6}$","why":"半徑忘了加 $1$：那是繞 $y$ 軸"},{"label":"$-\\dfrac{\\pi}{2}$","why":"內外顛倒了：體積不會是負的"},{"label":"$\\dfrac{\\pi}{30}$","why":"算成 $\\pi(R-r)^2$：要先平方再相減"}]}],"practice":[{"id":"cx-rev-003","core":true},{"id":"lec-09-q2d","core":true},{"id":"cg-5b-006","core":true},{"id":"cg-5b-007","core":true},{"id":"cg-5b-009","core":true},{"id":"cg-5b-012","core":true},{"id":"cg-5b-008"},{"id":"cg-5b-010"},{"id":"cg-5b-011"},{"id":"cg-5b-013"}]},"volume-shell":{"id":"volume-shell","prerequisites":["volume-washer"],"next":["volume-choose-method"],"related":["volume-disk"],"objectives":["知道圓殼法的切法：條子平行於旋轉軸，每一條掃出一個薄圓筒","寫出 $V=\\int 2\\pi$（半徑）（高）$dx$，半徑是條子到軸的距離","旋轉軸是 $x=k$ 時正確寫出半徑","繞 $x$ 軸時改成對 $y$ 積分"],"concept":[{"heading":"① 換一個方向切","body":["圓盤、墊圈：條子垂直於旋轉軸","這一課：條子平行於旋轉軸","例：$y=2x-x^2$ 與 $x$ 軸所圍區域，繞 $y$ 軸；取一條直的細條","整個立體 = 很多層薄圓筒套在一起"]},{"heading":"② 一個圓殼的體積","body":["攤平：長 $2\\pi r$（周長）、高 $h$、厚 $\\Delta r$","條子在 $x$：半徑 $x$、高 $f(x)$、厚 $dx$。全部加起來：","一般寫法：$V=\\displaystyle\\int 2\\pi\\,(\\text{半徑})(\\text{高})\\,dx$","為什麼「大約」可以變成等號：見 ⑤"],"tex":["\\Delta V\\approx2\\pi r\\cdot h\\cdot\\Delta r","V=\\int_a^b 2\\pi\\,x\\,f(x)\\,dx"]},{"heading":"③ 例：繞 y 軸","body":["$y=2x-x^2$、$x$ 軸所圍，繞 $y$ 軸；$x$ 從 $0$ 到 $2$","• 半徑：條子到 $y$ 軸的距離 $=x$","• 高：條子從 $x$ 軸到曲線 $=2x-x^2$"],"tex":["V=\\int_0^2 2\\pi x\\,(2x-x^2)\\,dx","=2\\pi\\int_0^2(2x^2-x^3)\\,dx","=2\\pi\\Big(\\frac{16}{3}-4\\Big)=\\frac{8\\pi}{3}"]},{"heading":"③ 例：繞 x = −1","body":["同一個區域，繞鉛直線 $x=-1$","高不變：$2x-x^2$；半徑 = 到 $x=-1$ 的距離 $=x-(-1)=x+1$","軸 $x=k$ 在左邊：半徑 $x-k$；在右邊：半徑 $k-x$"],"tex":["V=\\int_0^2 2\\pi(x+1)(2x-x^2)\\,dx","=2\\pi\\int_0^2(2x+x^2-x^3)\\,dx","=2\\pi\\Big(4+\\frac83-4\\Big)=\\frac{16\\pi}{3}"]},{"heading":"③ 繞 x 軸：對 y 積分","body":["$y=\\sqrt x$（$0\\le x\\le4$）與 $x$ 軸之間，繞 $x$ 軸，用圓殼法","條子要平行 $x$ 軸：水平的條子，厚 $dy$，$y$ 從 $0$ 到 $2$","• 半徑：到 $x$ 軸的距離 $=y$","• 高（條子長）：從 $x=y^2$ 到 $x=4$，$=4-y^2$","圓殼：條子平行於軸；積分變數跟條子的厚度方向"],"tex":["V=\\int_0^2 2\\pi y\\,(4-y^2)\\,dy","=2\\pi\\Big[2y^2-\\frac{y^4}{4}\\Big]_0^2=8\\pi"]},{"heading":"④ 為什麼要多學一種","body":["用墊圈算 $y=2x-x^2$ 繞 $y$ 軸：要水平切、對 $y$ 積分","要把 $x$ 解出來：$x=1\\pm\\sqrt{1-y}$，兩個分支","中括號化簡成 $4\\sqrt{1-y}$，積分得 $4\\cdot\\frac23$","更極端：$y=\\sin(x^2)$，$0\\le x\\le\\sqrt\\pi$，繞 $y$ 軸","令 $u=x^2$：$=\\pi\\displaystyle\\int_0^{\\pi}\\sin u\\,du=2\\pi$","圓殼的半徑 $x$ 常常剛好是代換需要的那個因子"],"tex":["\\pi\\int_0^1\\Big[(1+\\sqrt{1-y})^2-(1-\\sqrt{1-y})^2\\Big]dy","=\\frac{8\\pi}{3}","V=\\int_0^{\\sqrt\\pi}2\\pi x\\sin(x^2)\\,dx"]},{"heading":"⑤ 圓殼的精確體積","body":["內半徑 $r_1$、外半徑 $r_2$、高 $h$ 的圓殼：","令 $\\bar r=\\dfrac{r_1+r_2}{2}$（平均半徑）、$\\Delta r=r_2-r_1$：","把 $[a,b]$ 切成 $n$ 段，第 $i$ 段取中點 $\\bar x_i$，高用 $f(\\bar x_i)$：","這是 $2\\pi x f(x)$ 的 Riemann 和；$\\Delta x\\to0$：","嚴格說「兩種方法算出同一個體積」需要更多分析工具；下一課會用很多例子驗證"],"tex":["V=\\pi r_2^2h-\\pi r_1^2h=\\pi h\\,(r_2+r_1)(r_2-r_1)","V=2\\pi\\,\\bar r\\,h\\,\\Delta r","V\\approx\\sum_{i=1}^{n}2\\pi\\,\\bar x_i\\,f(\\bar x_i)\\,\\Delta x","V=\\int_a^b2\\pi x\\,f(x)\\,dx"]},{"heading":"重點整理","body":["• 條子平行於軸，掃出薄圓筒","• $V=\\int2\\pi\\,(\\text{半徑})(\\text{高})\\,dx$","• 半徑 = 條子到軸的距離：軸 $x=k$ 時 $\\lvert x-k\\rvert$","• 繞 $x$ 軸用圓殼：水平條子，對 $y$ 積分","• 好處：不用把 $x$ 解成 $y$","下一課：墊圈還是圓殼，怎麼選"]}],"workedExamples":[{"title":"繞 $y$ 軸","prompt":"區域由 $y=2x-x^2$ 與 $x$ 軸圍成，繞 $y$ 軸旋轉，求體積。","problemId":"lec-09-q2b","steps":["區域 $0\\le x\\le 2$。位在 $x$ 的直條：半徑 $x$，高 $2x-x^2$。","$V=\\int_0^2 2\\pi x(2x-x^2)\\,dx=2\\pi\\int_0^2(2x^2-x^3)\\,dx=2\\pi\\left(\\frac{16}{3}-4\\right)=2\\pi\\cdot\\frac{4}{3}=\\frac{8\\pi}{3}$。"],"answer":"$\\frac{8\\pi}{3}$"},{"title":"繞 $x=-1$","prompt":"同一個區域繞直線 $x=-1$ 旋轉，求體積。","problemId":"lec-09-q2c","steps":["高不變，還是 $2x-x^2$。半徑變成到 $x=-1$ 的距離：$x-(-1)=x+1$。","$V=\\int_0^2 2\\pi(x+1)(2x-x^2)\\,dx=2\\pi\\left[\\int_0^2(2x^2-x^3)\\,dx+\\int_0^2(2x-x^2)\\,dx\\right]=2\\pi\\left(\\frac{4}{3}+\\frac{4}{3}\\right)=\\frac{16\\pi}{3}$。"],"answer":"$\\frac{16\\pi}{3}$"},{"title":"繞 $x$ 軸，對 $y$ 積分","prompt":"$y=\\sqrt{x}$（$0\\le x\\le 4$）與 $x$ 軸之間的區域繞 $x$ 軸旋轉，用圓殼法求體積。","steps":["繞 $x$ 軸，條子要水平。$y$ 從 0 到 2；高度 $y$ 的橫條從 $x=y^2$ 到 $x=4$，長 $4-y^2$。","半徑是橫條到 $x$ 軸的距離 $y$。$V=\\int_0^2 2\\pi y(4-y^2)\\,dy=2\\pi(8-4)=8\\pi$。","對照〈圓盤法〉的範例 1：$\\int_0^4\\pi x\\,dx=8\\pi$，兩種方法答案一樣。"],"answer":"$8\\pi$"}],"pitfalls":["把圓殼的半徑和高寫反。","繞 $x=k$ 時半徑還寫 $x$。","公式裡漏了 $2\\pi$ 或漏了半徑，只積高度。","條子方向切錯：圓殼法的條子要平行於旋轉軸。"],"voice":"16e1c52c","sections":[{"title":"換一個方向切","beats":[{"show":["圓盤、墊圈：條子垂直於旋轉軸"],"say":"前兩課的圓盤和墊圈，都是把條子切成跟旋轉軸垂直，轉一圈得到一片圓盤或墊圈。","board":[{"do":"write","line":"圓盤、墊圈：條子垂直於旋轉軸"}],"t":[2980,11850]},{"show":["這一課：條子平行於旋轉軸"],"say":"這一課換一個方向：條子跟旋轉軸平行。","board":[{"do":"write","line":"這一課：條子平行於旋轉軸","color":"red"}],"t":[11850,16680]},{"show":["例：$y=2x-x^2$ 與 $x$ 軸所圍區域，繞 $y$ 軸；取一條直的細條"],"say":"例如 y 等於 2x 減 x 平方跟 x 軸圍成的區域，繞 y 軸旋轉。在 x 處取一條直立的細條，它跟 y 軸平行。","board":[{"do":"write","line":"例：$y=2x-x^2$ 與 $x$ 軸所圍區域，繞 $y$ 軸；取一條直的細條"}],"t":[16680,29580]}],"predict":{"ask":"一條平行於 $y$ 軸的細條，繞 $y$ 軸轉一圈，掃出來的是？","options":[{"label":"一個薄圓筒（圓殼）","correct":true},{"label":"一片圓盤","why":"圓盤是==垂直於==軸的條子掃出來的"},{"label":"一個墊圈","why":"墊圈也是垂直於軸的條子；平行的條子掃出筒壁"}]}},{"title":"換一個方向切","beats":[{"show":["整個立體 = 很多層薄圓筒套在一起"],"say":"答案是薄圓筒。整個立體，就像洋蔥或年輪，是很多層薄圓筒一層一層套起來的。這些薄圓筒叫做圓殼。","board":[{"do":"write","line":"整個立體 = 很多層薄圓筒套在一起"}],"t":[38260,50850]}]},{"title":"一個圓殼的體積","beats":[{"show":["圖"],"say":"一個圓殼：半徑 r、高 h、厚度德爾塔 r。沿著一條直線剪開、攤平，它幾乎就是一塊薄板。","board":[{"do":"plot","svg":"<svg viewBox=\"0 0 640 250\" width=\"640\"><line x1=\"170\" y1=\"15\" x2=\"170\" y2=\"240\" stroke=\"var(--muted)\" stroke-width=\"2\" stroke-dasharray=\"8 6\"/><path d=\"M 55 60 L 55 200 A 115 34 0 0 0 285 200 L 285 60 A 115 34 0 0 1 55 60 Z\" fill=\"#f5d56e\" fill-opacity=\"0.3\" stroke=\"none\"/><path d=\"M 55 200 A 115 34 0 0 1 285 200\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/><path d=\"M 55 60 A 115 34 0 1 0 285 60 A 115 34 0 1 0 55 60 Z M 78 60 A 92 27 0 1 0 262 60 A 92 27 0 1 0 78 60 Z\" fill=\"#f5d56e\" fill-opacity=\"0.8\" fill-rule=\"evenodd\" stroke=\"var(--blue)\" stroke-width=\"3\"/><line x1=\"55\" y1=\"60\" x2=\"55\" y2=\"200\" stroke=\"var(--blue)\" stroke-width=\"3\"/><line x1=\"285\" y1=\"60\" x2=\"285\" y2=\"200\" stroke=\"var(--blue)\" stroke-width=\"3\"/><path d=\"M 55 200 A 115 34 0 0 0 285 200\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"3\"/><line x1=\"170\" y1=\"60\" x2=\"273\" y2=\"60\" stroke=\"var(--red)\" stroke-width=\"3\"/><text x=\"205\" y=\"82\" text-anchor=\"middle\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:24px;fill:var(--red)\">r</text><text x=\"297\" y=\"140\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:28px;fill:var(--ink)\">h</text><text x=\"292\" y=\"24\" style=\"font-family:KaTeX_Main,serif;font-size:24px;fill:var(--ink)\">Δ<tspan style=\"font-family:KaTeX_Math,serif;font-style:italic\">r</tspan></text><line x1=\"300\" y1=\"30\" x2=\"278\" y2=\"52\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><text x=\"352\" y=\"120\" text-anchor=\"middle\" style=\"font-family:inherit;font-size:22px;fill:var(--ink)\">攤開</text><line x1=\"330\" y1=\"135\" x2=\"370\" y2=\"135\" stroke=\"var(--ink)\" stroke-width=\"2\"/><polygon points=\"370,135 362,130 362,140\" fill=\"var(--ink)\"/><polygon points=\"390,90 590,90 602,78 402,78\" fill=\"#f5d56e\" fill-opacity=\"0.8\" stroke=\"var(--blue)\" stroke-width=\"2\"/><polygon points=\"590,90 602,78 602,188 590,200\" fill=\"#f5d56e\" fill-opacity=\"0.8\" stroke=\"var(--blue)\" stroke-width=\"2\"/><rect x=\"390\" y=\"90\" width=\"200\" height=\"110\" fill=\"#f5d56e\" fill-opacity=\"0.3\" stroke=\"var(--blue)\" stroke-width=\"3\"/><text x=\"490\" y=\"232\" text-anchor=\"middle\" style=\"font-family:KaTeX_Main,serif;font-size:26px;fill:var(--ink)\">2π<tspan style=\"font-family:KaTeX_Math,serif;font-style:italic\">r</tspan></text><text x=\"560\" y=\"150\" text-anchor=\"middle\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:28px;fill:var(--ink)\">h</text><text x=\"608\" y=\"72\" style=\"font-family:KaTeX_Main,serif;font-size:22px;fill:var(--ink)\">Δ<tspan style=\"font-family:KaTeX_Math,serif;font-style:italic\">r</tspan></text></svg>"}],"t":[50850,64040]},{"show":["攤平：長 $2\\pi r$（周長）、高 $h$、厚 $\\Delta r$","$\\Delta V\\approx2\\pi r\\cdot h\\cdot\\Delta r$"],"say":"薄板的長，是圓筒的周長 2 派 r；高是 h；厚度是德爾塔 r。體積大約是三個相乘。","board":[{"do":"write","line":"攤平：長 $2\\pi r$（周長）、高 $h$、厚 $\\Delta r$"},{"do":"write","line":"${{bx1:\\displaystyle \\Delta V\\approx2\\pi r\\cdot h\\cdot\\Delta r}}$","on":"高是"},{"do":"box","term":"bx1","on":"體積"}],"t":[64040,75750]},{"show":["條子在 $x$：半徑 $x$、高 $f(x)$、厚 $dx$。全部加起來：","$V=\\int_a^b 2\\pi\\,x\\,f(x)\\,dx$"],"say":"對應回條子：在 x 處的條子，半徑是 x，高是 f of x，厚度 d x。全部加起來，取極限，就是圓殼法。","board":[{"do":"write","line":"條子在 $x$：半徑 $x$、高 $f(x)$、厚 $dx$。全部加起來："},{"do":"write","line":"${{bx2:\\displaystyle V=\\int_a^b 2\\pi\\,x\\,f(x)\\,dx}}$","color":"red","on":"高是"},{"do":"box","term":"bx2","color":"red","on":"全部"}],"t":[75750,87440]},{"show":["一般寫法：$V=\\displaystyle\\int 2\\pi\\,(\\text{半徑})(\\text{高})\\,dx$"],"say":"一般記成：2 派乘半徑乘高，再積分。半徑是條子到軸的距離，高是條子的長度。","board":[{"do":"write","line":"一般寫法：$V=\\displaystyle\\int 2\\pi\\,(\\text{半徑})(\\text{高})\\,dx$"},{"do":"write","line":"　為什麼「大約」可以變成等號：見 ⑤","color":"violet","on":"半徑#2"}],"t":[87440,97570]}]},{"title":"例：繞 y 軸","beats":[{"show":["$y=2x-x^2$、$x$ 軸所圍，繞 $y$ 軸；$x$ 從 $0$ 到 $2$"],"say":"回到例子。拋物線跟 x 軸交在 0 和 2，所以條子的位置 x 從 0 到 2。","board":[{"do":"write","line":"$y=2x-x^2$、$x$ 軸所圍，繞 $y$ 軸；$x$ 從 $0$ 到 $2$"}],"t":[97570,107620]},{"show":["• 半徑：條子到 $y$ 軸的距離 $=x$","• 高：條子從 $x$ 軸到曲線 $=2x-x^2$"],"say":"半徑：條子到 y 軸的距離，就是 x。高：條子從 x 軸長到曲線，是 2x 減 x 平方。","board":[{"do":"write","line":"• 半徑：條子到 $y$ 軸的距離 $=x$"},{"do":"write","line":"• 高：條子從 $x$ 軸到曲線 $=2x-x^2$","on":"子從"}],"t":[107620,119280]},{"show":["$V=\\int_0^2 2\\pi x\\,(2x-x^2)\\,dx$","$=2\\pi\\int_0^2(2x^2-x^3)\\,dx$"],"say":"寫成積分：2 派 x 乘 2x 減 x 平方，展開是 2x 平方減 x 立方。","board":[{"do":"write","line":"$\\displaystyle V=\\int_0^2 2\\pi x\\,(2x-x^2)\\,dx$"},{"do":"write","line":"$\\displaystyle =2\\pi\\int_0^2(2x^2-x^3)\\,dx$","on":"平方#1"}],"t":[119280,127480]},{"show":["$=2\\pi\\Big(\\frac{16}{3}-4\\Big)=\\frac{8\\pi}{3}$"],"say":"反導函數是 3 分之 2 x 立方減 4 分之 x 四次方。代 2：3 分之 16 減 4，等於 3 分之 4，乘 2 派，體積是 3 分之 8 派。","board":[{"do":"write","line":"${{bx3:\\displaystyle =2\\pi\\Big(\\frac{16}{3}-4\\Big)=\\frac{8\\pi}{3}}}$","color":"red"},{"do":"box","term":"bx3","color":"red","on":"16"}],"t":[127480,143580]},{"show":["紅條（高）繞 y 軸到虛線的位置；綠線是半徑 x"],"say":"圖上紅色是條子，長度就是高；綠色是它到 y 軸的距離，就是半徑。虛線是條子轉到另一邊的位置。","board":[{"do":"plot","nb":{"spec":{"id":"sh","window":[-2.3,2.3,-0.3,1.3],"fn":[{"expr":"2*x-x^2","color":"blue","label":"y = 2x − x²","domain":[0,2]},{"expr":"-2*x-x^2","color":"blue","dash":true,"domain":[-2,0]}],"area":[{"expr":"2*x-x^2","from":0,"to":2,"color":"blue"}],"lines":[{"from":["t",0],"to":["t","2*t-t^2"],"color":"red"},{"from":["-t",0],"to":["-t","2*t-t^2"],"color":"red","dash":true},{"from":[0,"0.5*(2*t-t^2)"],"to":["t","0.5*(2*t-t^2)"],"color":"green"}],"params":{"t":{"min":0.1,"max":1.9,"value":0.6,"label":"x"}},"height":260}}},{"do":"write","line":"紅條（高）繞 y 軸到虛線的位置；綠線是半徑 x","color":"violet","on":"色是#2"},{"do":"plot","nb":{"spec":{"id":"sh","window":[-2.3,2.3,-0.3,1.3],"fn":[{"expr":"2*x-x^2","color":"blue","label":"y = 2x − x²","domain":[0,2]},{"expr":"-2*x-x^2","color":"blue","dash":true,"domain":[-2,0]}],"area":[{"expr":"2*x-x^2","from":0,"to":2,"color":"blue"}],"lines":[{"from":["t",0],"to":["t","2*t-t^2"],"color":"red"},{"from":["-t",0],"to":["-t","2*t-t^2"],"color":"red","dash":true},{"from":[0,"0.5*(2*t-t^2)"],"to":["t","0.5*(2*t-t^2)"],"color":"green"}],"params":{"t":{"min":0.1,"max":1.9,"value":0.6,"label":"x"}},"height":260},"vals":{"t":1.5}},"on":"虛線"}],"t":[143580,158210]}]},{"title":"例：繞 x = −1","beats":[{"show":["同一個區域，繞鉛直線 $x=-1$"],"say":"同一個區域，改繞鉛直線 x 等於負 1。","board":[{"do":"write","line":"同一個區域，繞鉛直線 $x=-1$"}],"t":[158210,162950]},{"show":["高不變：$2x-x^2$；半徑 = 到 $x=-1$ 的距離 $=x-(-1)=x+1$"],"say":"條子的高不會變，還是 2x 減 x 平方。會變的是半徑：條子到 x 等於負 1 的距離，是 x 減負 1，也就是 x 加 1。","board":[{"do":"write","line":"高不變：$2x-x^2$；半徑 = 到 $x=-1$ 的距離 $=x-(-1)=x+1$","color":"gold"}],"t":[162950,177890]},{"show":["$V=\\int_0^2 2\\pi(x+1)(2x-x^2)\\,dx$","$=2\\pi\\int_0^2(2x+x^2-x^3)\\,dx$"],"say":"寫成積分，展開是 2x 加 x 平方減 x 立方。","board":[{"do":"write","line":"$\\displaystyle V=\\int_0^2 2\\pi(x+1)(2x-x^2)\\,dx$"},{"do":"write","line":"$\\displaystyle =2\\pi\\int_0^2(2x+x^2-x^3)\\,dx$","on":"平方"}],"t":[177890,183290]},{"show":["$=2\\pi\\Big(4+\\frac83-4\\Big)=\\frac{16\\pi}{3}$"],"say":"代 2 進去：4 加 3 分之 8 減 4，乘 2 派，體積是 3 分之 16 派。離軸遠了，體積變成兩倍。","board":[{"do":"write","line":"${{bx4:\\displaystyle =2\\pi\\Big(4+\\frac83-4\\Big)=\\frac{16\\pi}{3}}}$","color":"red"},{"do":"box","term":"bx4","color":"red","on":"體積#1"}],"t":[183290,195190]},{"show":["綠線（半徑）從 x = −1 量到條子：x + 1"],"say":"圖上，綠色的半徑從 x 等於負 1 量起，比剛才多了 1。","board":[{"do":"plot","nb":{"spec":{"id":"shk","window":[-1.6,2.3,-0.3,1.3],"fn":[{"expr":"2*x-x^2","color":"blue","label":"y = 2x − x²","domain":[0,2]}],"area":[{"expr":"2*x-x^2","from":0,"to":2,"color":"blue"}],"vlines":[{"x":-1,"color":"red"}],"lines":[{"from":["t",0],"to":["t","2*t-t^2"],"color":"red"},{"from":[-1,"0.5*(2*t-t^2)"],"to":["t","0.5*(2*t-t^2)"],"color":"green"}],"params":{"t":{"min":0.1,"max":1.9,"value":1.2,"label":"x"}},"height":240}}},{"do":"write","line":"綠線（半徑）從 x = −1 量到條子：x + 1","color":"violet","on":"量起"}],"t":[195190,201390]},{"show":["軸 $x=k$ 在左邊：半徑 $x-k$；在右邊：半徑 $k-x$"],"say":"一般來說，軸在條子左邊，半徑是 x 減 k；軸在右邊，半徑是 k 減 x。永遠是大減小，半徑才是正的。","board":[{"do":"write","line":"軸 $x=k$ 在左邊：半徑 $x-k$；在右邊：半徑 $k-x$","color":"gold"}],"t":[201390,213710]}]},{"title":"試一題","beats":[{"show":["$y=2x-x^2$ 與 $x$ 軸所圍區域，繞直線 $x=3$，體積的式子是？"],"say":"試一題：繞 x 等於 3。","t":[213710,225260]}],"check":0},{"title":"試一題","beats":[{"show":["$y=x^2$、$x$ 軸、$x=1$ 所圍區域繞 $y$ 軸，體積是？"],"say":"再一題：第一課留下來那個中間有洞的區域，用圓殼法一行就算完。","t":[225260,234240]}],"check":1},{"title":"繞 x 軸：對 y 積分","beats":[{"show":["$y=\\sqrt x$（$0\\le x\\le4$）與 $x$ 軸之間，繞 $x$ 軸，用圓殼法"],"say":"圓殼也可以繞 x 軸。用第一課的例子：根號 x 底下的區域，繞 x 軸。","board":[{"do":"write","line":"$y=\\sqrt x$（$0\\le x\\le4$）與 $x$ 軸之間，繞 $x$ 軸，用圓殼法"}],"t":[234240,242340]},{"show":["條子要平行 $x$ 軸：水平的條子，厚 $dy$，$y$ 從 $0$ 到 $2$"],"say":"條子要跟 x 軸平行，所以是水平的條子，厚度 d y，y 從 0 到 2。","board":[{"do":"write","line":"條子要平行 $x$ 軸：水平的條子，厚 $dy$，$y$ 從 $0$ 到 $2$"}],"t":[242340,251660]},{"show":["• 半徑：到 $x$ 軸的距離 $=y$","• 高（條子長）：從 $x=y^2$ 到 $x=4$，$=4-y^2$"],"say":"半徑是條子到 x 軸的距離，就是 y。條子的長度，從曲線 x 等於 y 平方，到右邊的 x 等於 4，長 4 減 y 平方。","board":[{"do":"write","line":"• 半徑：到 $x$ 軸的距離 $=y$"},{"do":"write","line":"• 高（條子長）：從 $x=y^2$ 到 $x=4$，$=4-y^2$","on":"等於#1"}],"t":[251660,266410]},{"show":["$V=\\int_0^2 2\\pi y\\,(4-y^2)\\,dy$","$=2\\pi\\Big[2y^2-\\frac{y^4}{4}\\Big]_0^2=8\\pi$"],"say":"積分：2 派乘 8 減 4，等於 8 派。跟第一課用圓盤法算的一樣。","board":[{"do":"write","line":"$\\displaystyle V=\\int_0^2 2\\pi y\\,(4-y^2)\\,dy$"},{"do":"write","line":"${{bx5:\\displaystyle =2\\pi\\Big[2y^2-\\frac{y^4}{4}\\Big]_0^2=8\\pi}}$","color":"red","on":"等於"},{"do":"box","term":"bx5","color":"red","on":"第一"}],"t":[266410,274760]},{"show":["水平的紅條繞 x 軸；綠線是半徑 y"],"say":"圖上，水平的紅條從曲線連到 x 等於 4，綠色是它到 x 軸的距離。","board":[{"do":"plot","nb":{"spec":{"id":"shx","window":[-0.3,4.5,-0.3,2.4],"fn":[{"expr":"sqrt(x)","color":"blue","label":"y = √x","domain":[0,4.3]}],"area":[{"expr":"sqrt(x)","from":0,"to":4,"color":"blue"}],"vlines":[{"x":4,"label":"x = 4"}],"lines":[{"from":["s^2","s"],"to":[4,"s"],"color":"red"},{"from":[2.6,0],"to":[2.6,"s"],"color":"green"}],"params":{"s":{"min":0.1,"max":1.9,"value":1.2,"label":"y"}},"height":240}}},{"do":"write","line":"水平的紅條繞 x 軸；綠線是半徑 y","color":"violet","on":"綠色"}],"t":[274760,282130]},{"show":["圓殼：條子平行於軸；積分變數跟條子的厚度方向"],"say":"記住：圓殼的條子平行於軸；厚度朝哪個方向，就對哪個變數積分。","board":[{"do":"write","line":"圓殼：條子平行於軸；積分變數跟條子的厚度方向","color":"gold"}],"t":[282130,290270]}]},{"title":"為什麼要多學一種","beats":[{"show":["用墊圈算 $y=2x-x^2$ 繞 $y$ 軸：要水平切、對 $y$ 積分"],"say":"為什麼要多學一種方法？試試用墊圈法算第一個例子：繞 y 軸，要水平切、對 y 積分。","board":[{"do":"write","line":"用墊圈算 $y=2x-x^2$ 繞 $y$ 軸：要水平切、對 $y$ 積分"}],"t":[290270,300270]},{"show":["要把 $x$ 解出來：$x=1\\pm\\sqrt{1-y}$，兩個分支"],"say":"就必須把 x 解成 y 的函數：x 等於 1 加減根號 1 減 y，有兩個分支，一個當外半徑、一個當內半徑。","board":[{"do":"write","line":"要把 $x$ 解出來：$x=1\\pm\\sqrt{1-y}$，兩個分支"}],"t":[300270,313420]},{"show":["$\\pi\\int_0^1\\Big[(1+\\sqrt{1-y})^2-(1-\\sqrt{1-y})^2\\Big]dy$","$=\\frac{8\\pi}{3}$"],"say":"硬算下去，答案一樣是 3 分之 8 派，但麻煩多了。圓殼法完全不用解 x。","board":[{"do":"write","line":"$\\displaystyle \\pi\\int_0^1\\Big[(1+\\sqrt{1-y})^2-(1-\\sqrt{1-y})^2\\Big]dy$"},{"do":"write","line":"$\\displaystyle =\\frac{8\\pi}{3}$","on":"分之"},{"do":"write","line":"　中括號化簡成 $4\\sqrt{1-y}$，積分得 $4\\cdot\\frac23$","color":"violet","on":"圓殼"}],"t":[313420,322670]},{"show":["更極端：$y=\\sin(x^2)$，$0\\le x\\le\\sqrt\\pi$，繞 $y$ 軸"],"say":"更極端的例子：正弦 x 平方，x 從 0 到根號派，繞 y 軸。用 y 表示 x 非常麻煩。","board":[{"do":"write","line":"更極端：$y=\\sin(x^2)$，$0\\le x\\le\\sqrt\\pi$，繞 $y$ 軸"}],"t":[322670,332270]},{"show":["$V=\\int_0^{\\sqrt\\pi}2\\pi x\\sin(x^2)\\,dx$"],"say":"用圓殼法：2 派 x 乘正弦 x 平方。剛好多出來的 x，讓我們可以做變數代換。","board":[{"do":"write","line":"$\\displaystyle V=\\int_0^{\\sqrt\\pi}2\\pi x\\sin(x^2)\\,dx$"}],"t":[332270,341120]},{"show":["令 $u=x^2$：$=\\pi\\displaystyle\\int_0^{\\pi}\\sin u\\,du=2\\pi$"],"say":"令 u 等於 x 平方，d u 是 2x d x，就變成派乘正弦 u 從 0 積到派，答案 2 派。","board":[{"do":"write","line":"令 $u=x^2$：$=\\pi\\displaystyle\\int_0^{\\pi}\\sin u\\,du=2\\pi$","color":"red"},{"do":"write","line":"　圓殼的半徑 $x$ 常常剛好是代換需要的那個因子","color":"violet","on":"就變"}],"t":[341120,354550]}]},{"title":"圓殼的精確體積","beats":[{"show":["內半徑 $r_1$、外半徑 $r_2$、高 $h$ 的圓殼：","$V=\\pi r_2^2h-\\pi r_1^2h=\\pi h\\,(r_2+r_1)(r_2-r_1)$"],"say":"最後說明為什麼公式是對的。內半徑 r 1、外半徑 r 2、高 h 的圓殼，精確體積是大圓柱減小圓柱，用平方差分解。","board":[{"do":"write","line":"內半徑 $r_1$、外半徑 $r_2$、高 $h$ 的圓殼："},{"do":"write","line":"$\\displaystyle V=\\pi r_2^2h-\\pi r_1^2h=\\pi h\\,(r_2+r_1)(r_2-r_1)$","on":"的圓"}],"t":[354550,368930]},{"show":["令 $\\bar r=\\dfrac{r_1+r_2}{2}$（平均半徑）、$\\Delta r=r_2-r_1$：","$V=2\\pi\\,\\bar r\\,h\\,\\Delta r$"],"say":"令平均半徑是兩個半徑的平均，厚度是 r 2 減 r 1。r 2 加 r 1 就是平均半徑的 2 倍，所以體積剛好等於 2 派乘平均半徑、乘高、乘厚度。是等號，不是近似。","board":[{"do":"write","line":"令 $\\bar r=\\dfrac{r_1+r_2}{2}$（平均半徑）、$\\Delta r=r_2-r_1$："},{"do":"write","line":"${{bx6:\\displaystyle V=2\\pi\\,\\bar r\\,h\\,\\Delta r}}$","color":"red","on":"就是"},{"do":"box","term":"bx6","color":"red","on":"等於"}],"t":[368930,389050]},{"show":["把 $[a,b]$ 切成 $n$ 段，第 $i$ 段取中點 $\\bar x_i$，高用 $f(\\bar x_i)$：","$V\\approx\\sum_{i=1}^{n}2\\pi\\,\\bar x_i\\,f(\\bar x_i)\\,\\Delta x$"],"say":"把 a 到 b 切成 n 段，每一段的條子轉成一個圓殼，平均半徑就是中點。唯一的近似，是把高當成常數，用中點的函數值。","board":[{"do":"write","line":"把 $[a,b]$ 切成 $n$ 段，第 $i$ 段取中點 $\\bar x_i$，高用 $f(\\bar x_i)$："},{"do":"write","line":"$\\displaystyle V\\approx\\sum_{i=1}^{n}2\\pi\\,\\bar x_i\\,f(\\bar x_i)\\,\\Delta x$","on":"均半"}],"t":[389050,403570]},{"show":["這是 $2\\pi x f(x)$ 的 Riemann 和；$\\Delta x\\to0$：","$V=\\int_a^b2\\pi x\\,f(x)\\,dx$"],"say":"這正是 2 派 x f of x 的黎曼和。段越切越細，高的誤差消失，和就收斂到定積分。","board":[{"do":"write","line":"這是 $2\\pi x f(x)$ 的 Riemann 和；$\\Delta x\\to0$："},{"do":"write","line":"${{bx7:\\displaystyle V=\\int_a^b2\\pi x\\,f(x)\\,dx}}$","on":"of"},{"do":"box","term":"bx7","on":"段越"},{"do":"write","line":"　嚴格說「兩種方法算出同一個體積」需要更多分析工具；下一課會用很多例子驗證","color":"violet","on":"和就"}],"t":[403570,420890]}]},{"title":"重點整理","beats":[{"show":["• 條子平行於軸，掃出薄圓筒","• $V=\\int2\\pi\\,(\\text{半徑})(\\text{高})\\,dx$"],"say":"整理一下：圓殼法的條子平行於軸，體積是 2 派乘半徑乘高的積分。半徑是條子到軸的距離；繞 x 軸就用水平條子對 y 積分。最大的好處，是不用反解函數。","board":[{"do":"write","line":"• 條子平行於軸，掃出薄圓筒"},{"do":"write","line":"• $V=\\int2\\pi\\,(\\text{半徑})(\\text{高})\\,dx$","on":"體積"},{"do":"write","line":"• 半徑 = 條子到軸的距離：軸 $x=k$ 時 $\\lvert x-k\\rvert$","on":"半徑#2"},{"do":"write","line":"• 繞 $x$ 軸用圓殼：水平條子，對 $y$ 積分","on":"軸就"},{"do":"write","line":"• 好處：不用把 $x$ 解成 $y$","on":"最大"}],"t":[420890,437350]},{"show":["下一課：墊圈還是圓殼，怎麼選"],"say":"下一課，學怎麼在墊圈和圓殼之間做選擇。","board":[{"do":"write","line":"下一課：墊圈還是圓殼，怎麼選"}],"t":[437350,444186]}]}],"checks":[{"ask":"$y=2x-x^2$ 與 $x$ 軸所圍區域，繞直線 $x=3$，體積的式子是？","options":[{"label":"$\\displaystyle\\int_0^2 2\\pi(3-x)(2x-x^2)\\,dx$","correct":true},{"label":"$\\displaystyle\\int_0^2 2\\pi(x-3)(2x-x^2)\\,dx$","why":"這樣半徑是負的：軸在右邊，要寫 $3-x$"},{"label":"$\\displaystyle\\int_0^2 2\\pi(x+3)(2x-x^2)\\,dx$","why":"這是繞 $x=-3$；$x+3$ 是到 $-3$ 的距離"},{"label":"$\\displaystyle\\int_0^2 2\\pi x(2x-x^2)\\,dx$","why":"這是繞 $y$ 軸；軸搬到 $x=3$，半徑要跟著改"}]},{"ask":"$y=x^2$、$x$ 軸、$x=1$ 所圍區域繞 $y$ 軸，體積是？","options":[{"label":"$\\dfrac{\\pi}{2}$","correct":true},{"label":"$\\dfrac{\\pi}{4}$","why":"少了 $2$：周長是 $2\\pi r$，不是 $\\pi r$"},{"label":"$\\dfrac{2\\pi}{3}$","why":"忘了乘半徑 $x$：$2\\pi\\int x^2dx$"},{"label":"$\\dfrac{\\pi}{5}$","why":"這是 $\\pi\\int x^4dx$：繞 $x$ 軸的圓盤，軸弄錯了"}]}],"practice":[{"id":"lec-09-m4","core":true},{"id":"cx-rev-005","core":true},{"id":"lec-09-q2b","core":true},{"id":"lec-09-q2c","core":true},{"id":"cg-5b-014","core":true},{"id":"cg-5b-016"},{"id":"cg-5b-015"},{"id":"cg-5b-017"}]},"volume-choose-method":{"id":"volume-choose-method","prerequisites":["volume-washer","volume-shell"],"next":["arc-length"],"related":["volume-disk","ibp-log-invtrig"],"objectives":["由旋轉軸的方向與切法，說出要對哪個變數積分","看邊界的寫法（$y=f(x)$ 還是 $x=g(y)$）挑出比較省事的方法","用另一種方法驗算同一個體積"],"concept":[{"heading":"① 先決定條子的方向","body":["兩種方法，差別只在條子怎麼擺：","• 條子垂直於軸 → 圓盤／墊圈","• 條子平行於軸 → 圓殼","積分變數 = 條子厚度的方向","• 繞水平軸（$x$ 軸、$y=k$）：墊圈對 $x$；圓殼對 $y$","• 繞鉛直軸（$y$ 軸、$x=h$）：墊圈對 $y$；圓殼對 $x$"]},{"heading":"② 再看哪個變數好寫","body":["邊界是 $y=f(x)$：對 $x$ 積分最省事","例：$y=2x-x^2$、$x$ 軸所圍，繞 $y$ 軸","圓殼（對 $x$）：一行寫完","墊圈（對 $y$）：要先解 $x=1\\pm\\sqrt{1-y}$","中括號化簡成 $4\\sqrt{1-y}$，答案一樣 $\\dfrac{8\\pi}{3}$，但多了解方程式"],"tex":["2\\pi\\int_0^2x(2x-x^2)\\,dx=\\frac{8\\pi}{3}","\\pi\\int_0^1\\Big[(1+\\sqrt{1-y})^2-(1-\\sqrt{1-y})^2\\Big]dy"]},{"heading":"② 試一題","body":["算出來：","判斷原則：哪個變數能把邊界寫成一條式子，就對它積分"],"tex":["2\\pi\\int_0^1(x^6+x^2)\\,dx=2\\pi\\Big(\\frac17+\\frac13\\Big)=\\frac{20\\pi}{21}"]},{"heading":"③ 兩種方法一定同一個答案","body":["例：$y=x$、$y=x^2$ 所圍，繞直線 $y=2$","墊圈（垂直條子，對 $x$）：軸在上方","• $R=2-x^2$（拋物線離軸遠）","• $r=2-x$（直線離軸近）"],"tex":["\\pi\\int_0^1\\big[(2-x^2)^2-(2-x)^2\\big]dx","=\\pi\\int_0^1(x^4-5x^2+4x)\\,dx","=\\pi\\Big(\\frac15-\\frac53+2\\Big)=\\frac{8\\pi}{15}"]},{"heading":"③ 用圓殼驗算","body":["兩邊不一樣 → 一定有一邊寫錯（通常是半徑）"],"tex":["2\\pi\\int_0^1\\big(2\\sqrt y-2y-y^{3/2}+y^2\\big)\\,dy","=2\\pi\\Big(\\frac43-1-\\frac25+\\frac13\\Big)=2\\pi\\cdot\\frac4{15}=\\frac{8\\pi}{15}"]},{"heading":"③ 這次墊圈比較好積","body":["$y=\\ln x$、$x$ 軸、$x=e$ 所圍，繞 $y$ 軸","圓殼（對 $x$）：$2\\pi\\displaystyle\\int_1^e x\\ln x\\,dx$","分部積分：$\\int x\\ln x\\,dx=\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}+C$","墊圈（對 $y$）：$y$ 從 $0$ 到 $1$，$x=e^y$ 好解","• $R=e$（右邊的直線 $x=e$）","• $r=e^y$（曲線 $y=\\ln x$）","圓殼用分部積分："],"tex":["\\pi\\int_0^1(e^2-e^{2y})\\,dy=\\pi\\Big(e^2-\\frac{e^2-1}{2}\\Big)=\\frac{\\pi(e^2+1)}{2}","2\\pi\\Big[\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}\\Big]_1^e=\\frac{\\pi(e^2+1)}{2}"]},{"heading":"④ 共用的一句話","body":["兩種方法都是同一句話：","一條條子轉一圈的體積，全部加起來","• 半徑永遠是到旋轉軸的距離","• 對條子厚度的方向積分","墊圈：$\\pi(R^2-r^2)\\cdot$厚；圓殼：$2\\pi\\cdot$半徑$\\cdot$高$\\cdot$厚"]},{"heading":"重點整理","body":["• 條子垂直於軸：墊圈；平行於軸：圓殼","• 積分變數 = 條子厚度的方向","• 邊界是 $y=f(x)$ → 對 $x$；好寫成 $x=g(y)$ → 對 $y$","• 兩種方法同一個答案：可以互相驗算","• 半徑永遠是到軸的距離","下一課：弧長"]}],"workedExamples":[{"title":"繞 $y$ 軸：圓殼省事","prompt":"$y=2x-x^2$ 與 $x$ 軸所圍區域繞 $y$ 軸旋轉。比較兩種方法。","problemId":"lec-09-q2b","steps":["圓殼：條子鉛直，對 $x$ 積分，邊界現成。$V=\\int_0^2 2\\pi x(2x-x^2)\\,dx=\\frac{8\\pi}{3}$。","墊圈：條子水平，對 $y$ 積分，要把 $y=2x-x^2$ 解成 $x$：$(x-1)^2=1-y$，$x=1\\pm\\sqrt{1-y}$。外半徑 $1+\\sqrt{1-y}$，內半徑 $1-\\sqrt{1-y}$。","$R^2-r^2=4\\sqrt{1-y}$，$V=\\pi\\int_0^1 4\\sqrt{1-y}\\,dy=4\\pi\\cdot\\frac{2}{3}=\\frac{8\\pi}{3}$。答案相同，但墊圈多了解方程式這一步。"],"answer":"$\\frac{8\\pi}{3}$"},{"title":"繞 $y=2$：兩種都好做，互相驗算","prompt":"$y=x$ 與 $y=x^2$ 所圍區域繞直線 $y=2$ 旋轉，求體積。","steps":["區域在 $y=2$ 下方。墊圈（對 $x$）：離軸較遠的是 $y=x^2$，$R=2-x^2$；$r=2-x$。$V=\\pi\\int_0^1((2-x^2)^2-(2-x)^2)\\,dx=\\pi\\int_0^1(4x-5x^2+x^4)\\,dx=\\pi\\left(2-\\frac{5}{3}+\\frac{1}{5}\\right)=\\frac{8\\pi}{15}$。","圓殼（對 $y$）：水平條從 $x=y$ 到 $x=\\sqrt{y}$，長 $\\sqrt{y}-y$；半徑 $2-y$。$V=\\int_0^1 2\\pi(2-y)(\\sqrt{y}-y)\\,dy=2\\pi\\left(\\frac{4}{3}-1-\\frac{2}{5}+\\frac{1}{3}\\right)=2\\pi\\cdot\\frac{4}{15}=\\frac{8\\pi}{15}$。","兩個方法一致。"],"answer":"$\\frac{8\\pi}{15}$"},{"title":"繞 $y$ 軸：這次墊圈比較好積","prompt":"$y=\\ln x$、$x$ 軸與 $x=e$ 所圍區域繞 $y$ 軸旋轉，求體積。","steps":["圓殼：$V=\\int_1^e 2\\pi x\\ln x\\,dx$，要用分部積分（〈ln x、反三角函數〉）。","墊圈：$y$ 從 0 到 1；在高度 $y$，橫條從 $x=e^y$ 到 $x=e$。外半徑 $e$，內半徑 $e^y$。","$V=\\pi\\int_0^1(e^2-e^{2y})\\,dy=\\pi\\left(e^2-\\frac{e^2-1}{2}\\right)=\\frac{\\pi(e^2+1)}{2}$。","用圓殼驗算：$\\int_1^e x\\ln x\\,dx=\\left[\\frac{x^2\\ln x}{2}-\\frac{x^2}{4}\\right]_1^e=\\frac{e^2}{4}+\\frac{1}{4}$，乘 $2\\pi$ 得 $\\frac{\\pi(e^2+1)}{2}$。"],"answer":"$\\frac{\\pi(e^2+1)}{2}$"}],"pitfalls":["記成「繞 $y$ 軸就用圓殼」：要看的是邊界好不好寫，不是只看軸。","方法選對了，積分變數卻沒跟著換。","旋轉軸不是座標軸時，只換了一種方法的半徑，另一種忘了換。","兩種方法答案不同時，以為是正常的誤差。"],"voice":"e9f9e3a6","sections":[{"title":"先決定條子的方向","beats":[{"show":["兩種方法，差別只在條子怎麼擺：","• 條子垂直於軸 → 圓盤／墊圈"],"say":"前三課學了兩種方法。它們的差別，只在條子怎麼擺：條子垂直於旋轉軸，是圓盤或墊圈；條子平行於旋轉軸，是圓殼。","board":[{"do":"write","line":"兩種方法，差別只在條子怎麼擺："},{"do":"write","line":"• 條子垂直於軸 → 圓盤／墊圈","on":"在條"},{"do":"write","line":"• 條子平行於軸 → 圓殼","on":"盤或"}],"t":[6840,20080]},{"show":["積分變數 = 條子厚度的方向"],"say":"條子一擺好，積分變數就決定了：條子的厚度朝哪個方向，就對哪個變數積分。","board":[{"do":"write","line":"積分變數 = 條子厚度的方向","color":"red"}],"t":[20080,31150]},{"show":["• 繞水平軸（$x$ 軸、$y=k$）：墊圈對 $x$；圓殼對 $y$","• 繞鉛直軸（$y$ 軸、$x=h$）：墊圈對 $y$；圓殼對 $x$"],"say":"整理成兩句：繞水平的軸，墊圈對 x 積分，圓殼對 y 積分。繞鉛直的軸，剛好反過來：墊圈對 y，圓殼對 x。","board":[{"do":"write","line":"• 繞水平軸（$x$ 軸、$y=k$）：墊圈對 $x$；圓殼對 $y$"},{"do":"write","line":"• 繞鉛直軸（$y$ 軸、$x=h$）：墊圈對 $y$；圓殼對 $x$","on":"積分#2"}],"t":[31150,43370]}],"check":0},{"title":"再看哪個變數好寫","beats":[{"show":["邊界是 $y=f(x)$：對 $x$ 積分最省事"],"say":"方向決定變數；反過來，選方法的時候，就看哪個變數好寫。邊界寫成 y 等於 f of x 的時候，對 x 積分最省事。","board":[{"do":"write","line":"邊界是 $y=f(x)$：對 $x$ 積分最省事"}],"t":[52330,64430]},{"show":["例：$y=2x-x^2$、$x$ 軸所圍，繞 $y$ 軸"],"say":"例子：y 等於 2x 減 x 平方跟 x 軸圍成的區域，繞 y 軸。上一課算過答案是 3 分之 8 派。","board":[{"do":"write","line":"例：$y=2x-x^2$、$x$ 軸所圍，繞 $y$ 軸"}],"t":[64430,76620]},{"show":["圓殼（對 $x$）：一行寫完","$2\\pi\\int_0^2x(2x-x^2)\\,dx=\\frac{8\\pi}{3}$"],"say":"繞鉛直軸，要對 x 積分就是圓殼。半徑 x，高 2x 減 x 平方，直接寫出來。","board":[{"do":"write","line":"圓殼（對 $x$）：一行寫完"},{"do":"write","line":"${{bx1:\\displaystyle 2\\pi\\int_0^2x(2x-x^2)\\,dx=\\frac{8\\pi}{3}}}$","on":"是圓"},{"do":"box","term":"bx1","on":"平方"}],"t":[76620,87700]},{"show":["墊圈（對 $y$）：要先解 $x=1\\pm\\sqrt{1-y}$","$\\pi\\int_0^1\\Big[(1+\\sqrt{1-y})^2-(1-\\sqrt{1-y})^2\\Big]dy$"],"say":"要用墊圈，就得對 y 積分，先把 x 解成 1 加減根號 1 減 y，兩個分支分別是外半徑和內半徑。","board":[{"do":"write","line":"墊圈（對 $y$）：要先解 $x=1\\pm\\sqrt{1-y}$"},{"do":"write","line":"$\\displaystyle \\pi\\int_0^1\\Big[(1+\\sqrt{1-y})^2-(1-\\sqrt{1-y})^2\\Big]dy$","on":"減根"}],"t":[87700,98800]},{"show":["紅：圓殼的條子（一條式子）；綠：墊圈的條子（兩端要解 x）"],"say":"圖上，紅色的直條，長度就是一條式子。綠色的橫條，兩端都要從拋物線解出 x 才寫得出來。","board":[{"do":"plot","nb":{"spec":{"id":"c1","window":[-0.3,2.3,-0.2,1.3],"fn":[{"expr":"2*x-x^2","color":"blue","label":"y = 2x − x²","domain":[0,2]}],"area":[{"expr":"2*x-x^2","from":0,"to":2,"color":"blue"}],"lines":[{"from":["t",0],"to":["t","2*t-t^2"],"color":"red"},{"from":["1-sqrt(1-s)","s"],"to":["1+sqrt(1-s)","s"],"color":"green"}],"params":{"t":{"min":0.1,"max":1.9,"value":0.4,"label":"圓殼條子 x"},"s":{"min":0.05,"max":0.95,"value":0.6,"label":"墊圈條子 y"}},"height":240}}},{"do":"write","line":"紅：圓殼的條子（一條式子）；綠：墊圈的條子（兩端要解 x）","color":"violet","on":"橫條"}],"t":[98800,109400]},{"show":["中括號化簡成 $4\\sqrt{1-y}$，答案一樣 $\\dfrac{8\\pi}{3}$，但多了解方程式"],"say":"硬算下去，中括號化簡成 4 倍根號 1 減 y，答案一樣，但多了一步解方程式。這題圓殼省事。","board":[{"do":"write","line":"中括號化簡成 $4\\sqrt{1-y}$，答案一樣 $\\dfrac{8\\pi}{3}$，但多了解方程式"}],"t":[109400,120640]}]},{"title":"試一題","beats":[{"show":["$y=x^5+x$、$x$ 軸、$x=1$ 所圍區域繞 $y$ 軸，哪個方法比較好？"],"say":"試一題：這個區域繞 y 軸，用哪一種方法？","t":[120640,132660]}],"check":1},{"title":"試一題","beats":[{"show":["算出來：","$2\\pi\\int_0^1(x^6+x^2)\\,dx=2\\pi\\Big(\\frac17+\\frac13\\Big)=\\frac{20\\pi}{21}$"],"say":"用圓殼：x 的六次方加 x 平方，積分是 7 分之 1 加 3 分之 1，乘 2 派，等於 21 分之 20 派。","board":[{"do":"write","line":"算出來："},{"do":"write","line":"${{bx2:\\displaystyle 2\\pi\\int_0^1(x^6+x^2)\\,dx=2\\pi\\Big(\\frac17+\\frac13\\Big)=\\frac{20\\pi}{21}}}$","on":"分之#1"},{"do":"box","term":"bx2","on":"等於"}],"t":[132660,144460]},{"show":["判斷原則：哪個變數能把邊界寫成一條式子，就對它積分"],"say":"判斷原則：看哪個變數能把邊界乾淨地寫成一條式子，就對那個變數積分；再由變數跟軸的方向，決定是墊圈還是圓殼。","board":[{"do":"write","line":"判斷原則：哪個變數能把邊界寫成一條式子，就對它積分","color":"red"}],"t":[144460,157220]}]},{"title":"兩種方法一定同一個答案","beats":[{"show":["例：$y=x$、$y=x^2$ 所圍，繞直線 $y=2$"],"say":"兩種方法量的是同一個立體，答案一定一樣。這題兩種都好做，剛好拿來互相驗算。y 等於 x 跟 y 等於 x 平方圍成的區域，繞 y 等於 2。","board":[{"do":"write","line":"例：$y=x$、$y=x^2$ 所圍，繞直線 $y=2$"}],"t":[157220,175290]},{"show":["墊圈（垂直條子，對 $x$）：軸在上方","• $R=2-x^2$（拋物線離軸遠）"],"say":"先用墊圈：垂直的條子，對 x 積分。軸在區域上方，距離是 2 減 y。下面的拋物線離軸遠，外半徑 2 減 x 平方；直線離軸近，內半徑 2 減 x。","board":[{"do":"write","line":"墊圈（垂直條子，對 $x$）：軸在上方"},{"do":"write","line":"• $R=2-x^2$（拋物線離軸遠）","on":"距離"},{"do":"write","line":"• $r=2-x$（直線離軸近）","on":"平方"}],"t":[175290,195170]},{"show":["$\\pi\\int_0^1\\big[(2-x^2)^2-(2-x)^2\\big]dx$","$=\\pi\\int_0^1(x^4-5x^2+4x)\\,dx$"],"say":"展開以後是 x 四次方減 5x 平方加 4x，積出來 5 分之 1 減 3 分之 5 加 2，等於 15 分之 8 派。","board":[{"do":"write","line":"$\\displaystyle \\pi\\int_0^1\\big[(2-x^2)^2-(2-x)^2\\big]dx$"},{"do":"write","line":"$\\displaystyle =\\pi\\int_0^1(x^4-5x^2+4x)\\,dx$","on":"平方"},{"do":"write","line":"${{bx3:\\displaystyle =\\pi\\Big(\\frac15-\\frac53+2\\Big)=\\frac{8\\pi}{15}}}$","color":"red","on":"分之#2"},{"do":"box","term":"bx3","color":"red","on":"等於"}],"t":[195170,208270]},{"show":["紅：墊圈的條子；綠：圓殼的條子"],"say":"圖上，紅色垂直的是墊圈的條子；綠色水平的是圓殼的條子。","board":[{"do":"plot","nb":{"spec":{"id":"c2","window":[-0.2,1.3,-0.2,2.3],"fn":[{"expr":"x","color":"blue","label":"y = x","domain":[0,1.2]},{"expr":"x^2","color":"green","label":"y = x²","domain":[0,1.15]}],"area":[{"expr":"x","from":0,"to":1,"color":"blue","under":"x^2"}],"hlines":[{"y":2,"label":"y = 2","color":"red"}],"lines":[{"from":["t","t^2"],"to":["t","t"],"color":"red"},{"from":["t","t"],"to":["t",2],"color":"pencil","dash":true},{"from":["t","t"],"to":["sqrt(t)","t"],"color":"green"}],"params":{"t":{"min":0.1,"max":0.9,"value":0.5,"label":"位置"}},"height":280}}},{"do":"write","line":"紅：墊圈的條子；綠：圓殼的條子","color":"violet","on":"墊圈"},{"do":"plot","nb":{"spec":{"id":"c2","window":[-0.2,1.3,-0.2,2.3],"fn":[{"expr":"x","color":"blue","label":"y = x","domain":[0,1.2]},{"expr":"x^2","color":"green","label":"y = x²","domain":[0,1.15]}],"area":[{"expr":"x","from":0,"to":1,"color":"blue","under":"x^2"}],"hlines":[{"y":2,"label":"y = 2","color":"red"}],"lines":[{"from":["t","t^2"],"to":["t","t"],"color":"red"},{"from":["t","t"],"to":["t",2],"color":"pencil","dash":true},{"from":["t","t"],"to":["sqrt(t)","t"],"color":"green"}],"params":{"t":{"min":0.1,"max":0.9,"value":0.5,"label":"位置"}},"height":280},"vals":{"t":0.3}},"on":"平的"}],"t":[208270,218330]}]},{"title":"用圓殼驗算","beats":[{"show":["同一個區域繞 $y=2$，改用圓殼法（水平條子），式子是？"],"say":"換用圓殼驗算。先選式子：半徑跟條子長度各是什麼？","t":[218330,229880]}],"check":2},{"title":"用圓殼驗算","beats":[{"show":["$2\\pi\\int_0^1\\big(2\\sqrt y-2y-y^{3/2}+y^2\\big)\\,dy$"],"say":"展開：2 倍根號 y、減 2y、減 y 的 2 分之 3 次方、加 y 平方。","board":[{"do":"write","line":"$\\displaystyle 2\\pi\\int_0^1\\big(2\\sqrt y-2y-y^{3/2}+y^2\\big)\\,dy$"}],"t":[229880,238080]},{"show":["$=2\\pi\\Big(\\frac43-1-\\frac25+\\frac13\\Big)=2\\pi\\cdot\\frac4{15}=\\frac{8\\pi}{15}$"],"say":"逐項積分，括號裡是 15 分之 4，乘 2 派，也是 15 分之 8 派。兩個方法對上了。","board":[{"do":"write","line":"${{bx4:\\displaystyle =2\\pi\\Big(\\frac43-1-\\frac25+\\frac13\\Big)=2\\pi\\cdot\\frac4{15}=\\frac{8\\pi}{15}}}$","color":"red"},{"do":"box","term":"bx4","color":"red","on":"也是"}],"t":[238080,247640]},{"show":["兩邊不一樣 → 一定有一邊寫錯（通常是半徑）"],"say":"考試時如果有空，用另一種方法驗算是很好的檢查。答案不一樣，就一定有一邊寫錯，最常見的是半徑。","board":[{"do":"write","line":"兩邊不一樣 → 一定有一邊寫錯（通常是半徑）"}],"t":[247640,259580]}]},{"title":"這次墊圈比較好積","beats":[{"show":["$y=\\ln x$、$x$ 軸、$x=e$ 所圍，繞 $y$ 軸"],"say":"最後一個例子：自然對數 x、x 軸、跟 x 等於 e 圍成的區域，繞 y 軸。","board":[{"do":"write","line":"$y=\\ln x$、$x$ 軸、$x=e$ 所圍，繞 $y$ 軸"}],"t":[259580,267780]},{"show":["圓殼（對 $x$）：$2\\pi\\displaystyle\\int_1^e x\\ln x\\,dx$"],"say":"用圓殼，對 x 積分：2 派 x 乘自然對數 x，從 1 積到 e。式子好寫，但要用分部積分。","board":[{"do":"write","line":"圓殼（對 $x$）：$2\\pi\\displaystyle\\int_1^e x\\ln x\\,dx$"},{"do":"write","line":"　分部積分：$\\int x\\ln x\\,dx=\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}+C$","color":"violet","on":"積到"}],"t":[267780,281440]},{"show":["墊圈（對 $y$）：$y$ 從 $0$ 到 $1$，$x=e^y$ 好解","• $R=e$（右邊的直線 $x=e$）"],"say":"用墊圈，對 y 積分：自然對數很好反解，x 等於 e 的 y 次方。水平條子從曲線到 x 等於 e，外半徑 e，內半徑 e 的 y 次方。","board":[{"do":"write","line":"墊圈（對 $y$）：$y$ 從 $0$ 到 $1$，$x=e^y$ 好解"},{"do":"write","line":"• $R=e$（右邊的直線 $x=e$）","on":"次方#1"},{"do":"write","line":"• $r=e^y$（曲線 $y=\\ln x$）","on":"外半"}],"t":[281440,295640]},{"show":["$\\pi\\int_0^1(e^2-e^{2y})\\,dy=\\pi\\Big(e^2-\\frac{e^2-1}{2}\\Big)=\\frac{\\pi(e^2+1)}{2}$"],"say":"積分：e 平方減 e 的 2y 次方，結果是 2 分之派乘 e 平方加 1。不用分部積分。","board":[{"do":"write","line":"${{bx5:\\displaystyle \\pi\\int_0^1(e^2-e^{2y})\\,dy=\\pi\\Big(e^2-\\frac{e^2-1}{2}\\Big)=\\frac{\\pi(e^2+1)}{2}}}$","color":"red"},{"do":"box","term":"bx5","color":"red","on":"分之"}],"t":[295640,305740]},{"show":["水平的紅條：左端 x = e^y，右端 x = e"],"say":"圖上的紅色水平條，左端在曲線上，右端在 x 等於 e。轉一圈是一個墊圈。","board":[{"do":"plot","nb":{"spec":{"id":"c3","window":[-0.3,3.1,-0.3,1.3],"fn":[{"expr":"ln(x)","color":"blue","label":"y = ln x","domain":[0.6,3]}],"area":[{"expr":"ln(x)","from":1,"to":2.71828,"color":"blue"}],"vlines":[{"x":2.71828,"label":"x = e"}],"lines":[{"from":["exp(s)","s"],"to":[2.71828,"s"],"color":"red"}],"params":{"s":{"min":0.05,"max":0.95,"value":0.5,"label":"y"}},"height":240}}},{"do":"write","line":"水平的紅條：左端 x = e^y，右端 x = e","color":"violet","on":"等於"}],"t":[305740,315560]},{"show":["圓殼用分部積分：","$2\\pi\\Big[\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}\\Big]_1^e=\\frac{\\pi(e^2+1)}{2}$"],"say":"用圓殼加分部積分，答案一樣是 2 分之派乘 e 平方加 1，約 13.2。所以不是圓殼永遠比較好：反函數好寫時，墊圈可能更省事。","board":[{"do":"write","line":"圓殼用分部積分："},{"do":"write","line":"$\\displaystyle 2\\pi\\Big[\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}\\Big]_1^e=\\frac{\\pi(e^2+1)}{2}$","on":"13"}],"t":[315560,330250]}]},{"title":"共用的一句話","beats":[{"show":["兩種方法都是同一句話："],"say":"最後，把兩種方法收成一句話。","board":[{"do":"write","line":"兩種方法都是同一句話："}],"t":[330250,334550]},{"show":["一條條子轉一圈的體積，全部加起來"],"say":"都是：一條條子轉一圈的體積，全部加起來。","board":[{"do":"write","line":"一條條子轉一圈的體積，全部加起來","color":"red"}],"t":[334550,341540]},{"show":["• 半徑永遠是到旋轉軸的距離","• 對條子厚度的方向積分"],"say":"而且兩種方法共用兩個規則：半徑永遠是到旋轉軸的距離；積分變數永遠跟著條子的厚度。","board":[{"do":"write","line":"• 半徑永遠是到旋轉軸的距離"},{"do":"write","line":"• 對條子厚度的方向積分","on":"半徑"},{"do":"write","line":"　墊圈：$\\pi(R^2-r^2)\\cdot$厚；圓殼：$2\\pi\\cdot$半徑$\\cdot$高$\\cdot$厚","color":"violet","on":"積分"}],"t":[341540,351590]}],"proof":true,"order":{"ask":"求旋轉體體積的步驟","steps":[{"label":"畫出區域和旋轉軸，找交點"},{"label":"看邊界哪個變數好寫，決定條子方向（墊圈或圓殼）","why":"先要有上一步：畫出區域和旋轉軸，找交點"},{"label":"寫出半徑（到軸的距離）和高或內外半徑","why":"先要有上一步：看邊界哪個變數好寫，決定條子方向（墊圈或圓殼）"},{"label":"定上下限，積分","why":"先要有上一步：寫出半徑（到軸的距離）和高或內外半徑"},{"label":"有空：用另一種方法驗算","why":"先要有上一步：定上下限，積分"}]}},{"title":"重點整理","beats":[{"show":["• 條子垂直於軸：墊圈；平行於軸：圓殼","• 積分變數 = 條子厚度的方向"],"say":"整理一下：條子垂直於軸是墊圈，平行是圓殼；積分變數跟著條子的厚度。看哪個變數好寫來選方法，兩種方法答案一定一樣，可以互相驗算。","board":[{"do":"write","line":"• 條子垂直於軸：墊圈；平行於軸：圓殼"},{"do":"write","line":"• 積分變數 = 條子厚度的方向","on":"墊圈"},{"do":"write","line":"• 邊界是 $y=f(x)$ → 對 $x$；好寫成 $x=g(y)$ → 對 $y$","on":"跟著"},{"do":"write","line":"• 兩種方法同一個答案：可以互相驗算","on":"數好"},{"do":"write","line":"• 半徑永遠是到軸的距離","on":"案一"}],"t":[370880,385930]},{"show":["下一課：弧長"],"say":"下一課，用同樣的切小段想法，來算曲線的長度：弧長。","board":[{"do":"write","line":"下一課：弧長"}],"t":[385930,394136]}]}],"checks":[{"ask":"區域繞直線 $y=-2$ 旋轉，想用==圓殼法==，要對哪個變數積分？","options":[{"label":"$y$","correct":true},{"label":"$x$","why":"對 $x$ 積分的是墊圈法：垂直條子垂直於水平軸"},{"label":"兩個都可以","why":"方法一選定，條子方向就定了，變數也跟著定"}]},{"ask":"$y=x^5+x$、$x$ 軸、$x=1$ 所圍區域繞 $y$ 軸，哪個方法比較好？","options":[{"label":"圓殼：$2\\pi\\int_0^1x(x^5+x)\\,dx$","correct":true},{"label":"墊圈：對 $y$ 積分","why":"要把 $y=x^5+x$ 解成 $x=g(y)$：五次方程式解不出公式"},{"label":"兩種一樣好","why":"墊圈要反解 $x$，這裡辦不到"}]},{"ask":"同一個區域繞 $y=2$，改用圓殼法（水平條子），式子是？","options":[{"label":"$2\\pi\\displaystyle\\int_0^1(2-y)(\\sqrt y-y)\\,dy$","correct":true},{"label":"$2\\pi\\displaystyle\\int_0^1y(\\sqrt y-y)\\,dy$","why":"$y$ 是到 $x$ 軸的距離；軸是 $y=2$"},{"label":"$2\\pi\\displaystyle\\int_0^1(2-y)(y-\\sqrt y)\\,dy$","why":"長度反了：$0<y<1$ 時 $\\sqrt y>y$，右端是 $x=\\sqrt y$"},{"label":"$2\\pi\\displaystyle\\int_0^1(y-2)(\\sqrt y-y)\\,dy$","why":"軸在上方，$y-2<0$：半徑要寫 $2-y$"}]}],"practice":[{"id":"lec-09-q2a","core":true},{"id":"lec-09-q2b","core":true},{"id":"lec-09-q2c","core":true},{"id":"lec-09-q2d","core":true},{"id":"cg-5b-018","core":true},{"id":"cg-5b-021","core":true},{"id":"lec-09-m4","note":"兩種方法各做一次：圓殼 $2\\pi\\int_0^1 x\\cdot x\\,dx$，墊圈 $\\pi\\int_0^1(1-y^2)\\,dy$。"},{"id":"cx-rev-005"},{"id":"cx-rev-004"},{"id":"cg-5b-019"},{"id":"cg-5b-020"},{"id":"cg-5b-022"}]}});
